V7_BANKS_FINAL = {
    "truth": V7_TRUTH,
    "dare": V7_DARE,
    "mind": V7_MIND,
    "flirty": V7_FLIRTY,
    "scenario": V7_SCENARIO,
    "adult": V7_ADULT_COMMON,
    "adult_male": V7_ADULT_MALE,
    "adult_female": V7_ADULT_FEMALE,
    "penalty": V7_PENALTIES,
}


# adult_male and adult_female are PARALLEL banks: the same prompt may validly
# exist in both because they are never mixed into one draw pool (the picker
# selects by the answerer's gender). The dedupe keeps one copy per parallel
# group instead of dropping cross-duplicates globally.
V7_PARALLEL_BANK_GROUPS = ({"adult_male", "adult_female"},)


def _v7_parallel_group(key: str) -> set[str] | None:
    for grp in V7_PARALLEL_BANK_GROUPS:
        if key in grp:
            return grp
    return None


def v7_dedupe_bank_map(bank_map: dict[str, list[str]]) -> dict[str, list[str]]:
    """Deduplication policy:
    - Within every bank each prompt is unique.
    - A prompt used by a NON-parallel bank may not reappear in any other bank.
    - The PARALLEL banks (adult_male / adult_female) intentionally share many
      prompts: the same explicit question must be askable to a boy and to a
      girl alike, so shared prompts are kept in BOTH sibling banks and are not
      registered in the global seen-set."""
    seen: set[str] = set()
    out: dict[str, list[str]] = {}
    for key, items in bank_map.items():
        parallel = _v7_parallel_group(key) is not None
        local: set[str] = set()
        result = []
        for raw in items:
            text = str(raw).strip()
            if not text or text in local:
                continue
            if text in seen:
                continue
            local.add(text)
            if not parallel:
                seen.add(text)
            result.append(text)
        out[key] = result
    return out


