        rows = []
        cats = [("truth","🕵️ اعتراف"),("dare","🔥 جرئت"),("mind","🧠 ذهنی"),("scenario","🎭 سناریو"),("flirty","💘 فلرت"),("adult","🔞 بالغ"),("penalty","☠️ حکم"),("boss","👑 Boss")]
