    assert AR14_VERSION == "14.0"
    assert len(AR14_COMMANDS) == 5
    assert AR14_COMMAND_NAMES == ["start", "game", "profile", "rank", "help"]
    assert ar14_commands_match(AR14_COMMANDS)
