# ============================================================================
# APEX RIVAL 15.0 - RELIABLE GROUP ACCESS + COMMAND MENU REPAIR
# ---------------------------------------------------------------------------
# Goals of this layer:
#   1) A private /start is a one-time account activation. Group use never
#      forces the user through the same activation loop again.
#   2) Verification survives Render restarts as long as Telegram still knows
#      the bot's private chat with that user. We use get_chat() as the primary
#      durable signal and the private command scope as a secondary marker.
#   3) /game creates the lobby through a fresh, simple path instead of the long
#      chain of legacy wrappers that accumulated over earlier versions.
#   4) Exactly five visible commands are published everywhere. Legacy handler
#      aliases remain callable manually, but are not advertised by Telegram.
#   5) Stale chat/admin/member command scopes are repaired aggressively for the
#      current group/user, including the user's current Telegram language.
# ============================================================================
AR15_VERSION = "15.0"
BOT_VERSION = ADVANCED_VERSION = AR15_VERSION

AR15_COMMANDS = [
    BotCommand("start", "شروع و فعال‌سازی حساب"),
    BotCommand("game", "ساخت یا ورود به Lobby"),
    BotCommand("profile", "نمایش پروفایل"),
    BotCommand("rank", "نمایش رتبه‌بندی"),
    BotCommand("help", "راهنما و قوانین بازی"),
]
AR15_COMMAND_NAMES = [c.command for c in AR15_COMMANDS]
AR15_COMMAND_SIGNATURE = tuple((str(c.command), str(c.description)) for c in AR15_COMMANDS)
AR15_SCOPE_CACHE: dict[tuple[int, int, str], float] = {}
AR15_VERIFIED_CACHE: dict[int, tuple[float, str]] = {}
AR15_NEGATIVE_CACHE: dict[int, float] = {}
AR15_PRIVATE_MARKER_CACHE: dict[int, tuple[float, bool]] = {}
AR15_SCOPE_TTL = 1800.0
AR15_VERIFY_TTL = 21600.0
AR15_NEGATIVE_TTL = 20.0
AR15_LANGUAGE_FALLBACKS = ("fa", "en", "nl", "ar", "tr", "ru")


def ar15_commands_match(commands) -> bool:
    try:
        return tuple((str(c.command), str(c.description)) for c in (commands or [])) == AR15_COMMAND_SIGNATURE
    except Exception:
        return False


def ar15_user_language(update=None) -> str | None:
    try:
        user = getattr(update, "effective_user", None)
        lang = str(getattr(user, "language_code", "") or "").lower().split("-")[0].strip()
        return lang if re.fullmatch(r"[a-z]{2}", lang) else None
    except Exception:
        return None


async def ar15_force_scope5(bot, scope, language_code: str | None = None, *, verify: bool = True) -> bool:
    """Write five commands, verify, and repair once more if a stale scope remains."""
    try:
        await bot.set_my_commands(AR15_COMMANDS, scope=scope)
        if language_code:
            try:
                await bot.set_my_commands(AR15_COMMANDS, scope=scope, language_code=language_code)
            except Exception as lang_exc:
                print(f"ApexRival AR15 language scope warning ({language_code}): {lang_exc!r}")
        if not verify:
            return True
        got = await bot.get_my_commands(scope=scope)
        if not ar15_commands_match(got):
            # Retry the base scope below. A narrow language scope is audited
            # separately so a stale language-specific list cannot survive.
            pass
        elif not language_code:
            return True
        if language_code:
            try:
                lang_got = await bot.get_my_commands(scope=scope, language_code=language_code)
                if ar15_commands_match(lang_got):
                    return True
            except Exception as lang_read_exc:
                print(f"ApexRival AR15 language audit warning ({language_code}): {lang_read_exc!r}")
        elif ar15_commands_match(got):
            return True
        # A narrow stale scope can sometimes survive an earlier set. Remove the
        # scope then recreate it. Telegram documents deleteMyCommands as the
        # way to drop an override and fall back to a higher-level command list.
        try:
            await bot.delete_my_commands(scope=scope)
        except Exception:
            pass
        await bot.set_my_commands(AR15_COMMANDS, scope=scope)
        if language_code:
            try:
                await bot.set_my_commands(AR15_COMMANDS, scope=scope, language_code=language_code)
            except Exception:
                pass
        got2 = await bot.get_my_commands(scope=scope)
        base_ok = ar15_commands_match(got2)
        if language_code:
            try:
                lang_got2 = await bot.get_my_commands(scope=scope, language_code=language_code)
                return base_ok and ar15_commands_match(lang_got2)
            except Exception:
                return base_ok
        return base_ok
    except Exception as exc:
        print(f"ApexRival AR15 command-scope repair failed ({getattr(scope, 'type', '?')}): {exc!r}")
        return False


async def ar15_repair_group_scopes(bot, chat_id: int, user_id: int | None = None, language_code: str | None = None, *, force: bool = False) -> None:
    chat_id = int(chat_id)
    uid = int(user_id or 0)
    lang = language_code if language_code in AR15_LANGUAGE_FALLBACKS else None
    cache_key = (chat_id, uid, lang or "")
    now = time.time()
    if not force and now - AR15_SCOPE_CACHE.get(cache_key, 0.0) < AR15_SCOPE_TTL:
        return

    scopes = [
        BotCommandScopeChat(chat_id=chat_id),
        BotCommandScopeChatAdministrators(chat_id=chat_id),
    ]
    if uid:
        scopes.append(BotCommandScopeChatMember(chat_id=chat_id, user_id=uid))
    for scope in scopes:
        await ar15_force_scope5(bot, scope, lang, verify=True)
    AR15_SCOPE_CACHE[cache_key] = now


async def ar15_configure_command_scopes(application) -> None:
    """Normalize all broad scopes to exactly five commands at startup."""
    bot = application.bot
    broad = [
        BotCommandScopeDefault(),
        BotCommandScopeAllPrivateChats(),
        BotCommandScopeAllGroupChats(),
        BotCommandScopeAllChatAdministrators(),
    ]
    for scope in broad:
        await ar15_force_scope5(bot, scope, None, verify=True)
        # Persian is the bot's primary UI language; also normalize a few common
        # language scopes so a stale language-specific list cannot resurrect old
        # commands for those clients.
        for lang in AR15_LANGUAGE_FALLBACKS:
            try:
                await ar15_force_scope5(bot, scope, lang, verify=True)
            except Exception:
                pass

    # Existing groups get their explicit chat/admin scopes repaired immediately.
    # Member scopes are additionally repaired for users we already know took part
    # in a game/lobby; current members are fixed on their next group interaction.
    for raw_gid, group in list(DATA.get("groups", {}).items()):
        try:
            gid = int(raw_gid)
            await ar15_repair_group_scopes(bot, gid, None, None, force=True)
        except Exception as exc:
            print(f"ApexRival AR15 tracked-group scope warning: {exc!r}")

    for game in list(DATA.get("games", {}).values()):
        try:
            gid = int(game.get("chat_id", 0) or 0)
            if not gid or gid >= 0:
                continue
            players = [int(x) for x in game.get("players", [])]
            for uid in players[:50]:
                await ar15_repair_group_scopes(bot, gid, uid, None, force=True)
        except Exception as exc:
            print(f"ApexRival AR15 known-player scope warning: {exc!r}")

    try:
        audit_scopes = [
            ("default", BotCommandScopeDefault()),
            ("private", BotCommandScopeAllPrivateChats()),
            ("groups", BotCommandScopeAllGroupChats()),
            ("admins", BotCommandScopeAllChatAdministrators()),
        ]
        counts = []
        for name, scope in audit_scopes:
            got = await bot.get_my_commands(scope=scope)
            counts.append(f"{name}={len(got)}")
        print("ApexRival AR15 command audit | " + " | ".join(counts) + " | target=5")
    except Exception as exc:
        print(f"ApexRival AR15 command audit warning: {exc!r}")


async def ar15_mark_private_scope(uid: int, bot=None, language_code: str | None = None) -> None:
    bot = bot or APEX_RUNTIME_BOT
    if bot is None:
        return
    uid = int(uid)
    ok = await ar15_force_scope5(bot, BotCommandScopeChat(chat_id=uid), language_code, verify=True)
    AR15_PRIVATE_MARKER_CACHE[uid] = (time.time(), bool(ok))


async def ar15_get_private_marker(uid: int, bot=None, *, force: bool = False) -> tuple[bool | None, str]:
    uid = int(uid)
    now = time.time()
    cached = AR15_PRIVATE_MARKER_CACHE.get(uid)
    if not force and cached and now - cached[0] < AR15_VERIFY_TTL:
        return cached[1], "cached_private_scope"
    bot = bot or APEX_RUNTIME_BOT
    if bot is None:
        return None, "no_runtime_bot"
    try:
        got = await bot.get_my_commands(scope=BotCommandScopeChat(chat_id=uid))
        ok = ar15_commands_match(got)
        AR15_PRIVATE_MARKER_CACHE[uid] = (now, ok)
        return ok, "private_scope_marker" if ok else "no_private_scope_marker"
    except Exception as exc:
        print(f"ApexRival AR15 private marker read warning for {uid}: {exc!r}")
        return None, "private_scope_read_error"


async def ar15_record_lifetime_verified(uid: int, *, bot=None, source="private_start", language_code=None) -> None:
    uid = int(uid)
    u = get_user(uid)
    activation = u.setdefault("activation", {})
    first = int(activation.get("private_started_at", 0) or now_ts())
    activation.update({
        "version": 3,
        "ever_verified": True,
        "lifetime_access": True,
        "private_chat_id": uid,
        "private_started_at": first,
        "last_verified_at": now_ts(),
        "verified_source": str(source)[:80],
    })
    DATA.setdefault("started_users", {})[str(uid)] = first
    save_data(force=True)
    AR15_VERIFIED_CACHE[uid] = (time.time(), str(source))
    AR15_NEGATIVE_CACHE.pop(uid, None)
    await ar15_mark_private_scope(uid, bot=bot, language_code=language_code)


async def ar15_lifetime_check(uid: int, *, bot=None, force=False) -> tuple[bool | None, str]:
    """Return True only when a one-time activation signal exists.

    Primary durable signal after a Render restart: Telegram still has the bot's
    private chat with the user, which can be queried with getChat. This means a
    user who really ran /start does not have to do it again after local files are
    reset. The per-chat command scope remains a secondary remote marker.
    """
    uid = int(uid)
    u = get_user(uid)
    activation = u.setdefault("activation", {})
    now = time.time()

    if bool(activation.get("ever_verified")) or bool(activation.get("lifetime_access")) or v7_has_started(uid):
        activation["ever_verified"] = True
        activation["lifetime_access"] = True
        activation["private_chat_id"] = uid
        AR15_VERIFIED_CACHE[uid] = (now, "local_lifetime")
        return True, "local_lifetime"

    cached = AR15_VERIFIED_CACHE.get(uid)
    if not force and cached and now - cached[0] < AR15_VERIFY_TTL:
        return True, cached[1]
    if not force and uid in AR15_NEGATIVE_CACHE and now - AR15_NEGATIVE_CACHE[uid] < AR15_NEGATIVE_TTL:
        return False, "negative_cache"

    bot = bot or APEX_RUNTIME_BOT
    if bot is None:
        return None, "no_runtime_bot"

    # FIRST: ask Telegram whether the private chat exists. This is the simplest
    # durable fact: the bot cannot get a normal private chat object for someone
    # it has never interacted with.
    try:
        chat = await bot.get_chat(uid)
        if str(getattr(chat, "type", "")).lower() == "private":
            await ar15_record_lifetime_verified(uid, bot=bot, source="telegram_private_chat", language_code=None)
            return True, "telegram_private_chat"
    except Exception as exc:
        print(f"ApexRival AR15 private-chat recovery warning for {uid}: {exc!r}")

    # SECOND: read the Telegram-side activation marker if the chat-specific scope
    # was created by an earlier successful /start.
    marker, reason = await ar15_get_private_marker(uid, bot=bot, force=force)
    if marker is True:
        await ar15_record_lifetime_verified(uid, bot=bot, source="telegram_private_scope", language_code=None)
        return True, "telegram_private_scope"

    AR15_NEGATIVE_CACHE[uid] = now
    return False, reason


async def ar15_group_gate(update: Update, *, allow_admin: bool = True) -> bool:
    user = getattr(update, "effective_user", None)
    if not user:
        return False
    uid = int(user.id)
    if allow_admin and is_admin(uid):
        return True
    if not v7_chat_is_group(update):
        return True

    # Always repair the current user's effective command scope while we already
    # have the update. This fixes stale 11/12-command menus after the first
    # interaction even when the group has a narrower member-specific scope.
    bot = getattr(update, "bot", None) or APEX_RUNTIME_BOT
    chat = getattr(update, "effective_chat", None)
    if bot is not None and chat is not None:
        try:
            await ar15_repair_group_scopes(bot, int(chat.id), uid, ar15_user_language(update), force=False)
        except Exception as exc:
            print(f"ApexRival AR15 live scope repair warning: {exc!r}")

    verified, reason = await ar15_lifetime_check(uid, bot=bot, force=False)
    if verified is True:
        get_group(int(getattr(chat, "id", 0) or 0))
        return True

    msg = getattr(update, "message", None)
    query = getattr(update, "callback_query", None)
    username = await ar11_bot_username(bot)
    private_url = ar11_private_activate_url(username)
    rows = []
    if private_url:
        rows.append([ApexInlineButton("🚀 فعال‌سازی یک‌باره", url=private_url, style=APEX_STYLE_SUCCESS)])
    rows.append([ApexInlineButton("🔄 بررسی دوباره", callback_data="REQ|CHECK", style=APEX_STYLE_PRIMARY)])
    text = (
        "🔐 <b>یک‌بار فعال‌سازی حساب</b>\n\n"
        "برای این حساب هنوز فعال‌سازی خصوصی ثبت نشده است.\n"
        "<b>این مرحله فقط یک‌بار انجام می‌شود.</b> بعد از اینکه /start را در چت خصوصی ApexRival اجرا کردی، لازم نیست دوباره انجامش بدهی؛ حتی بعد از ری‌استارت سرویس.\n\n"
        "بعد از فعال‌سازی، همین‌جا برگرد و <b>/game</b> را بزن."
    )
    try:
        if query:
            await safe_answer_query(query, "🔐 این حساب هنوز فعال نشده است.", True)
            await query.message.reply_text(text, parse_mode=ParseMode.HTML, reply_markup=v5_markup(rows))
        elif msg:
            await msg.reply_text(text, parse_mode=ParseMode.HTML, reply_markup=v5_markup(rows))
    except Exception:
        pass
    return False


# Every legacy gate now delegates to the one-time lifetime gate.
v7_require_started = ar15_group_gate


async def ar15_ensure_allowed(update: Update) -> bool:
    user = getattr(update, "effective_user", None)
    if not user:
        return False
    uid = int(user.id)
    get_user(uid, getattr(user, "first_name", None) or getattr(user, "username", None) or "کاربر")
    if is_banned(uid) and not is_admin(uid):
        query = getattr(update, "callback_query", None)
        message = getattr(update, "message", None)
        if query:
            await safe_answer_query(query, "🚫 دسترسی شما مسدود است.", True)
        elif message:
            await message.reply_text("🚫 دسترسی شما به ApexRival مسدود شده است.")
        return False
    return await ar15_group_gate(update)


ensure_allowed = ar15_ensure_allowed


async def ar15_start(update, context):
    """Stable /start wrapper: group /start never re-prompts activated users."""
    user = getattr(update, "effective_user", None)
    msg = getattr(update, "message", None)
    if not user or not msg:
        return
    uid = int(user.id)
    bot = getattr(context, "bot", None) or APEX_RUNTIME_BOT

    if not ar12_private_only(update):
        # If the user really activated previously, do NOT show the old
        # "activation from group is impossible" loop. Recover remotely.
        verified, _ = await ar15_lifetime_check(uid, bot=bot, force=False)
        if verified is True:
            await ar15_repair_group_scopes(bot, int(update.effective_chat.id), uid, ar15_user_language(update), force=True)
            await ar12_remove_legacy_group_keyboard(update)
            if not user_gender(uid):
                # [GEN] Activated but genderless: prompt the choice right here.
                await msg.reply_text(
                    "✅ <b>حساب تو فعال است — فقط یک قدم مانده!</b>\n\n"
                    "🚻 برای شخصی‌سازی سؤال‌ها (به‌ویژه بخش 🔞 ۱۸+) جنسیتت را انتخاب کن:",
                    parse_mode=ParseMode.HTML,
                    reply_markup=gender_prompt_markup(),
                )
                return
            await msg.reply_text(
                "✅ <b>حساب تو قبلاً فعال شده است.</b>\n\n"
                "دیگر نیازی به /start خصوصی نداری. برای ساخت یا ورود به Lobby، <b>/game</b> را همین‌جا بزن.",
                parse_mode=ParseMode.HTML,
                reply_markup=ReplyKeyboardRemove(),
            )
            return
        await ar12_remove_legacy_group_keyboard(update)
        username = await ar11_bot_username(bot)
        private_url = ar11_private_activate_url(username)
        rows = []
        if private_url:
            rows.append([ApexInlineButton("🚀 فعال‌سازی یک‌باره", url=private_url, style=APEX_STYLE_SUCCESS)])
        rows.append([ApexInlineButton("🔄 بررسی دوباره", callback_data="REQ|CHECK", style=APEX_STYLE_PRIMARY)])
        await msg.reply_text(
            "🔐 <b>این حساب هنوز فعال نشده است.</b>\n\n"
            "فقط یک‌بار چت خصوصی ApexRival را باز کن و /start را اجرا کن. بعد از آن، این مرحله برای همیشه برای حسابت تمام می‌شود.",
            parse_mode=ParseMode.HTML,
            reply_markup=v5_markup(rows),
        )
        return

    # Private /start uses the mature channel check. Once it succeeds, AR15
    # records the lifetime marker and the exact-five command scope remotely.
    if is_banned(uid) and not is_admin(uid):
        await msg.reply_text("🚫 دسترسی این حساب به ApexRival مسدود است.", reply_markup=ReplyKeyboardRemove())
        return

    args = getattr(context, "args", None) or []
    source = "private_start"
    if args:
        source = f"start:{str(args[0])[:40]}"

    if not is_admin(uid):
        membership, _ = await ar8_channel_membership(uid, force=True, bot=bot)
        if membership is not True:
            text = ar8_prereq_text("need_channel") if membership is False else ar8_prereq_text("check_error")
            await msg.reply_text(text, parse_mode=ParseMode.HTML, reply_markup=await ar11_gate_markup(bot))
            return

    v7_mark_started(uid, source=source)
    AR11_PRIVATE_CACHE[uid] = (time.time(), True, "direct_start")
    st = ar11_activation_state(uid)
    st["source"] = source
    st["last_verified_at"] = now_ts()
    await ar15_record_lifetime_verified(uid, bot=bot, source=source, language_code=ar15_user_language(update))
    u = get_user(uid, user.first_name or user.username or "بازیکن")
    # [GEN] Gender is mandatory: right after activation we ask for پسر/دختر.
    # Until it is chosen, the private home menu is withheld (the GEN| callback
    # handler completes activation and then renders the home screen).
    if not user_gender(uid):
        u["gender"] = ""
        save_data(force=True)
        audit("gender_prompt_shown", uid, int(msg.chat_id), "after_activation")
        await msg.reply_text(
            gender_prompt_text(uid),
            parse_mode=ParseMode.HTML,
            reply_markup=gender_prompt_markup(),
        )
        return
    await msg.reply_text(
        ar12_private_home_text(uid) + "\n\n✅ <b>حساب خصوصی با موفقیت فعال شد.</b>\n🔐 <b>تأیید بعدی لازم نیست.</b>",
        parse_mode=ParseMode.HTML,
        reply_markup=ar12_private_home_markup(uid),
    )


async def ar15_gender_callback(update, context):
    """[GEN] Handles the mandatory پسر/دختر selection from /start."""
    query = getattr(update, "callback_query", None)
    if not query or not query.data:
        return
    data = str(query.data)
    if not data.startswith("GEN|"):
        return
    uid = int(getattr(getattr(query, "from_user", None), "id", 0) or 0)
    if not uid:
        return
    choice = "male" if data == "GEN|M" else "female" if data == "GEN|F" else ""
    if not choice:
        return
    u = get_user(uid)
    existing = user_gender(uid)
    if existing:
        # Already locked: tell the player their registered gender.
        await safe_answer_query(
            query,
            f"جنسیت تو قبلاً ثبت شده: {GENDER_LABELS[existing]} — قابل تغییر نیست.",
            True,
        )
        return
    u["gender"] = choice
    save_data(force=True)
    audit("gender_set", uid, int(getattr(getattr(query, "message", None), "chat_id", 0) or 0), choice)
    await safe_answer_query(query, f"✅ ثبت شد: {GENDER_LABELS[choice]}")
    # Now deliver the full private home menu (activation was already done).
    try:
        await safe_edit_query(
            query,
            ar12_private_home_text(uid)
            + f"\n\n{user_gender_icon(uid)} جنسیت: <b>{GENDER_LABELS[choice]}</b>"
            + "\n✅ <b>حساب خصوصی با موفقیت فعال شد.</b>\n🔓 همهٔ امکانات باز شد.",
            ar12_private_home_markup(uid),
        )
    except Exception:
        try:
            await query.message.reply_text(
                ar12_private_home_text(uid) + f"\n\n{user_gender_icon(uid)} جنسیت: <b>{GENDER_LABELS[choice]}</b>",
                parse_mode=ParseMode.HTML,
                reply_markup=ar12_private_home_markup(uid),
            )
        except Exception:
            pass


start = v5_start = v7_start = ar15_start


async def ar15_create_lobby(update, context):
    """Fresh, deterministic group /game implementation."""
    user = getattr(update, "effective_user", None)
    chat = getattr(update, "effective_chat", None)
    msg = getattr(update, "message", None)
    if not user or not chat or not msg:
        return
    uid = int(user.id)
    bot = getattr(context, "bot", None) or APEX_RUNTIME_BOT

    if not v7_chat_is_group(update):
        await msg.reply_text("🎮 <b>/game مخصوص گروه است.</b> برای منوی شخصی، /start را در چت خصوصی بزن.", parse_mode=ParseMode.HTML)
        return

    if not await ar15_ensure_allowed(update):
        return
    if is_banned(uid) and not is_admin(uid):
        await msg.reply_text("🚫 دسترسی این حساب به بازی محدود شده است.")
        return

    try:
        await ar12_remove_legacy_group_keyboard(update)
    except Exception:
        pass

    group = get_group(int(chat.id))
    if not group.get("enabled", True) and not is_admin(uid):
        await msg.reply_text("🚫 ApexRival در این گروه خاموش است.")
        return

    current = active_game(int(chat.id))
    if current:
        current["_viewer_id"] = uid
        if current.get("status") == "lobby":
            await msg.reply_text(ar13_lobby_text(current), parse_mode=ParseMode.HTML, reply_markup=ar13_lobby_markup(current))
        else:
            await msg.reply_text(v7_turn_card(current), parse_mode=ParseMode.HTML, reply_markup=v7_turn_markup(current, int(current.get("current_questioner") or current.get("leader_id") or uid)))
        return

    name = getattr(user, "first_name", None) or getattr(user, "username", None) or "سرگروه"
    game = make_game(int(chat.id), uid, name)
    game["ready"] = {str(uid): True}
    game["phase"] = "lobby"
    game["status"] = "lobby"
    game["_viewer_id"] = uid
    game["created_at"] = now_ts()
    game["invite_token"] = ar13_lobby_invite_token(game)
    v5_touch(game)
    save_data(force=True)
    await msg.reply_text(ar13_lobby_text(game), parse_mode=ParseMode.HTML, reply_markup=ar13_lobby_markup(game))


v5_create_lobby = ar15_create_lobby


async def ar15_group_scope_background(update, context):
    try:
        if not v7_chat_is_group(update):
            return
        chat = getattr(update, "effective_chat", None)
        user = getattr(update, "effective_user", None)
        bot = getattr(context, "bot", None) or getattr(update, "bot", None) or APEX_RUNTIME_BOT
        if not chat or not user or bot is None:
            return
        # [FIX 14] force=True bypassed the 30-minute scope cache and fired ~3
        # setMyCommands API calls for EVERY message, quickly hitting Telegram
        # rate limits in active groups. The cache still repairs stale menus.
        await ar15_repair_group_scopes(bot, int(chat.id), int(user.id), ar15_user_language(update), force=False)
    except Exception as exc:
        print(f"ApexRival AR15 background command repair warning: {exc!r}")


# A final callback bridge keeps both old V5 cancel buttons and new A13 cancel
# buttons working, while applying the one-time group gate first.
async def ar15_callback_dispatch(update, context):
    query = getattr(update, "callback_query", None)
    if not query or not query.data:
        return
    data = str(query.data)
    if not v7_chat_is_group(update):
        return
    if not await ar15_group_gate(update):
        return

    if data.startswith("A13|L|"):
        # Let the mature A13 lobby controller handle cancel/ready/lock/kick/host.
        await ar13_handle_callback(update, context)
        return

    if data.startswith("V5|L|"):
        # Existing V5 buttons route through the hardened v5_lobby_action bridge.
        try:
            parts = data.split("|")
            await v5_lobby_action(query, context, parts)
        except Exception as exc:
            audit("ar15_v5_lobby_callback_error", int(query.from_user.id), getattr(query.message, "chat_id", None), repr(exc)[:500])
            await safe_answer_query(query, "⚠️ عملیات Lobby انجام نشد. دوباره امتحان کن.", True)
        return


async def ar15_callback_check(update, context):
    query = getattr(update, "callback_query", None)
    if not query:
        return
    data = str(getattr(query, "data", "") or "")
    if not data.startswith("REQ|"):
        return
    uid = int(getattr(getattr(query, "from_user", None), "id", 0) or 0)
    bot = getattr(context, "bot", None) or APEX_RUNTIME_BOT
    verified, reason = await ar15_lifetime_check(uid, bot=bot, force=True)
    if verified is True:
        await safe_answer_query(query, "✅ حساب قبلاً فعال شده؛ تکرار /start لازم نیست.")
        try:
            if v7_chat_is_group(update):
                await ar15_repair_group_scopes(bot, int(query.message.chat_id), uid, None, force=True)
                await safe_edit_query(query, "✅ <b>حسابت فعال است.</b>\n\nحالا /game را در همین گروه بزن.", v5_markup([[v5_button("🎮 ساخت Lobby", "V5|GAME")]]))
            else:
                if not user_gender(uid):
                    # [GEN] genderless activated account: ask for پسر/دختر now.
                    await safe_edit_query(query, gender_prompt_text(uid), gender_prompt_markup())
                else:
                    await safe_edit_query(query, ar12_private_home_text(uid), ar12_private_home_markup(uid))
        except Exception:
            pass
        return
    await safe_answer_query(query, "🔐 هنوز فعال‌سازی خصوصی برای این حساب ثبت نشده است.", True)


async def ar15_post_init(application):
    try:
        await ar12_post_init(application)
    except Exception as exc:
        print(f"ApexRival AR15 legacy post-init warning: {exc!r}")
    await ar15_configure_command_scopes(application)
    await ar11_bot_username(application.bot)


def ar15_register_handlers(app):
    # Re-register command handlers against the FINAL function objects.
    app.add_handler(CommandHandler("start", ar15_start))
    app.add_handler(CommandHandler("game", ar15_create_lobby))
    app.add_handler(CommandHandler("profile", v5_profile_message))
    app.add_handler(CommandHandler("rank", v5_rank_message))
    app.add_handler(CommandHandler("help", v5_help_message))

    # Hidden compatibility commands remain callable manually without appearing
    # in Telegram's five-command suggestion menu.
    app.add_handler(CommandHandler("verify", ar8_verify_cmd))
    app.add_handler(CommandHandler("menu", v5_menu))
    app.add_handler(CommandHandler("shop", shop_cmd))
    app.add_handler(CommandHandler("achievements", achievements_cmd))
    app.add_handler(CommandHandler("id", id_cmd))
    app.add_handler(CommandHandler("admin", ar12_admin_entry))
    app.add_handler(CommandHandler("adult", adult_cmd))
    app.add_handler(CommandHandler("bazi", ar15_create_lobby))
    app.add_handler(CommandHandler("man", v5_menu))
    app.add_handler(CommandHandler("rahnama", v5_help_message))

    # Check activation buttons before old callback routers.
    # [FIX 2] The old group=-50 dispatch for A13|L|/V5|L| overlapped the
    # group-0 handlers (python-telegram-bot runs ONE handler per group, so
    # BOTH ran). Every lobby action executed twice: the ready/lock toggles
    # canceled themselves, kicks alerted an error after succeeding, and
    # starting the game produced two messages. The single-execution group-0
    # chain below already routes V5|L|S -> v7_start_lobby (turn engine) and
    # applies the same AR15 gates, so the duplicate dispatch is removed.
    app.add_handler(CallbackQueryHandler(ar15_callback_check, pattern=r"^REQ\|CHECK"), group=-60)

    # [GEN] Mandatory gender selection (پسر/دختر) — runs before every other
    # callback router so the prompt can never be swallowed by legacy dispatch.
    app.add_handler(CallbackQueryHandler(ar15_gender_callback, pattern=r"^GEN\|"), group=-70)

    # Generic handlers from the mature bot remain available for the rest of the UI.
    app.add_handler(CallbackQueryHandler(ar12_callback_dispatch, pattern=r"^(ADM\||V5\||V7\|)"))
    app.add_handler(CallbackQueryHandler(ar13_handle_callback, pattern=r"^A13\|"))
    # [FIX 2b] REQ|INFO opens the guided channel/activation info screen
    # (previously it fell into ar15_callback_check and behaved like CHECK).
    app.add_handler(CallbackQueryHandler(ar8_prereq_callback, pattern=r"^REQ\|INFO"))
    # [FIX 2c] The shop's buy buttons and the penalty item buttons emit legacy
    # callback payloads (buy|..., penaltyshield|..., penaltypass|...). They had
    # NO handler at all in the AR15 wiring, so purchases silently did nothing.
    # The mature v3 callback router (ar6-wrapped for shop gating) handles them.
    app.add_handler(CallbackQueryHandler(callback, pattern=r"^(buy\||penaltydone\||penaltyshield\||penaltypass\|)"))

    # Live scope repair for the current group/member. It never blocks gameplay.
    try:
        app.add_handler(MessageHandler(filters.ALL, ar15_group_scope_background, block=False), group=-100)
    except Exception:
        try:
            app.add_handler(MessageHandler(filters.TEXT, ar15_group_scope_background, block=False), group=-100)
        except Exception:
            pass

    # Preserve the mature text router for non-command messages.
    try:
        app.add_handler(MessageHandler(filters.TEXT & ~filters.COMMAND, ar12_text_router))
    except Exception:
        pass


def ar15_static_self_check():
    assert AR15_VERSION == "15.0"
    assert len(AR15_COMMANDS) == 5
    assert AR15_COMMAND_NAMES == ["start", "game", "profile", "rank", "help"]
    assert ar15_commands_match(AR15_COMMANDS)
    assert callable(ar15_start)
    assert callable(ar15_create_lobby)
    assert callable(ar15_group_gate)
    assert callable(ar15_configure_command_scopes)
    assert callable(ar15_lifetime_check)
    for c in AR15_COMMANDS:
        assert 1 <= len(str(c.command)) <= 32
        assert str(c.command) == str(c.command).lower()
        assert all(ch.isascii() and (ch.islower() or ch.isdigit() or ch == "_") for ch in str(c.command))
    for sample in (
        "A13|L|C|123456",
        "A13|L|CY|123456",
        "V5|L|J|123456",
        "REQ|CHECK",
    ):
        assert 1 <= len(sample.encode("utf-8")) <= 64
    src = Path(__file__).read_text(encoding="utf-8")
    assert "ar15_lifetime_check" in src
    assert "ar15_create_lobby" in src
    assert "ar15_force_scope5" in src
    print(
        "ApexRival AR15 static self-check OK | "
        "lifetime-verification=on | direct-chat-recovery=on | commands=5 | "
        "fresh-lobby=on | scoped-repair=on"
    )


ar15_static_self_check()


# ================================================================
# ================================================================
#  APEXRIVAL v16 «MEGA LAYER» — گروه‌محور، بدون گیت مرگ
#  [FIX-LOBBY] ریشه‌ای‌ترین رفع باگ «کسی نمی‌تواند عضو لابی شود»:
#  گیت‌های انباشته (فعال‌سازی خصوصی + عضویت کانال اجباری + جنسیت)
#  دیگر مسیر عضویت/بازی را نمی‌بندند؛ به پرامپت‌های نرم تبدیل شدند.
# ================================================================
# ================================================================

AR16_VERSION = "16.0"


def ar16_gate_mode() -> str:
    """حالت گیت گروه. پیش‌فرض "off" = عضویت و بازی همیشه کار می‌کند.
    "on" = رفتار سخت‌گیرانه‌ی قدیم (کانال + فعال‌سازی اجباری)."""
    try:
        return str(DATA.setdefault("settings", {}).get("group_gate_mode", "off") or "off").strip().lower()
    except Exception:
        return "off"


def v16_maintenance() -> bool:
    try:
        return bool(DATA["settings"].get("maintenance", False))
    except Exception:
        return False


# ----------------------------------------------------------------
# [FIX-LOBBY 1/7] گیت نهایی گروه — دیگر به صورت پیش‌فرض بازی را قفل
# نمی‌کند. (این تابع توسط v7_require_started / ar15_ensure_allowed /
# v5_callback / v7_callback / v5_text_router همه به اسم سراسری فراخوانی
# می‌شود، پس این بازتعریف همه‌ی مسیرها را یکجا شفا می‌دهد.)
# ----------------------------------------------------------------
_AR16_OLD_GROUP_GATE = ar15_group_gate


async def ar15_group_gate(update, *, allow_admin: bool = True):
    user = getattr(update, "effective_user", None)
    if not user:
        return False
    if ar16_gate_mode() != "on":
        # حالت باز: هیچ‌وقت بازی گروهی را به خاطر فعال‌سازی/کانال قفل نکن.
        return True
    return await _AR16_OLD_GROUP_GATE(update, allow_admin=allow_admin)


v7_require_started = ar15_group_gate
ensure_allowed = v7_ensure_allowed


# ----------------------------------------------------------------
# [FIX-LOBBY 2/7] عضویت هوشمند — هر عضو گروه با یک دکمه وارد می‌شود؛
# ثبت‌نام خودکار + کارت‌های راهنمای نرم (جنسیت/فعال‌سازی) بعد از ورود.
# ----------------------------------------------------------------
async def ar16_smart_join(query, game):
    uid = int(query.from_user.id)
    try:
        if game.get("status") != "lobby":
            await safe_answer_query(query, "⛔ ثبت‌نام این Lobby بسته شده است.", True)
            return
        if v5_is_player(game, uid):
            game["_viewer_id"] = uid
            await safe_answer_query(query, "✅ تو همین الان ثبت‌نامی!", False)
            await safe_edit_query(query, ar13_lobby_text(game), ar13_lobby_markup(game))
            return
        if ar13_lobby_locked(game) and not leader_of(game, uid) and not is_admin(uid):
            await safe_answer_query(query, "🔒 سرگروه ثبت‌نام را موقتاً بسته است.", True)
            return
        max_p = int(game.get("settings", {}).get("max_players", 20))
        if len(game.get("players", [])) >= max_p:
            await safe_answer_query(query, "⛔ ظرفیت Lobby تکمیل است.", True)
            return
        # [FIX-LOBBY] خودکار ثبت‌نام کاربر — بدون نیاز به /start خصوصی
        first_name = getattr(query.from_user, "first_name", None) or getattr(query.from_user, "username", None) or "بازیکن"
        get_user(uid, first_name)
        game.setdefault("players", []).append(uid)
        game.setdefault("names", {})[str(uid)] = first_name
        v5_ready_state(game)[str(uid)] = True
        game["_viewer_id"] = uid
        v5_touch(game)
        audit("v5_join", uid, int(game.get("chat_id", 0)), f"smart:{game.get('id')}")
        save_data(force=True)
        await safe_answer_query(query, "✅ وارد Lobby شدی!")
        await safe_edit_query(query, ar13_lobby_text(game), ar13_lobby_markup(game))
        # ---- کارت‌های راهنمای نرم (غیرمسدودکننده، هر کدام فقط یک بار) ----
        try:
            need_gender = not user_gender(uid)
            need_start = not v7_has_started(uid)
            if need_gender or need_start:
                bot = getattr(query, "get_bot", lambda: None)() or APEX_RUNTIME_BOT
                username = await ar11_bot_username(bot)
                private_url = ar11_private_activate_url(username)
                lines = ["🎟 <b>ثبت‌نامت کامل شد!</b>", ""]
                if need_gender:
                    lines += [
                        "🚻 فقط یک قدم: <b>جنسیتت</b> را انتخاب کن تا سؤال‌ها (به‌ویژه بخش 🔞) دقیقاً مناسب خودت ساخته شوند:",
                        "",
                    ]
                if need_start:
                    lines += [
                        "🔑 پیشنهاد: ربات را یک‌بار در چت خصوصی <b>/start</b> کن تا پروفایل، امتیاز و نشان‌هایت برای همیشه فعال شود.",
                        "",
                    ]
                rows = []
                if need_gender:
                    rows.append([
                        v5_button("👦 پسر", "V16|G|M"),
                        v5_button("👧 دختر", "V16|G|F"),
                    ])
                if need_start and private_url:
                    rows.append([ApexInlineButton("🚀 فعال‌سازی در چت خصوصی", url=private_url, style=APEX_STYLE_SUCCESS)])
                await query.message.reply_text("\n".join(lines), parse_mode=ParseMode.HTML, reply_markup=v5_markup(rows))
        except Exception as exc:
            print(f"ApexRival V16 join followup warning: {exc!r}")
    except Exception as exc:
        audit("v16_smart_join_error", uid, None, repr(exc)[:300])
        try:
            await safe_answer_query(query, "⚠️ عضویت انجام نشد؛ دوباره امتحان کن.", True)
        except Exception:
            pass


# هندلر جنسیت در بستر گروه (دکمه‌های V16|G|*) — بدون اسپام منوی خصوصی
async def v16_gender_callback(update, context):
    query = getattr(update, "callback_query", None)
    if not query or not query.data:
        return
    data = str(query.data)
    if not data.startswith("V16|G|"):
        return
    uid = int(query.from_user.id)
    choice = "male" if data == "V16|G|M" else "female"
    existing = user_gender(uid)
    if existing:
        await safe_answer_query(query, f"جنسیت تو قبلاً ثبت شده: {GENDER_LABELS[existing]} — قابل تغییر نیست.", True)
        return
    u = get_user(uid)
    u["gender"] = choice
    save_data(force=True)
    audit("gender_set", uid, int(getattr(query.message, "chat_id", 0) or 0), choice + ":group")
    icon = user_gender_icon(uid)
    await safe_answer_query(query, f"✅ ثبت شد: {GENDER_LABELS[choice]}")
    await safe_edit_query(
        query,
        f"{icon} <b>جنسیتت ثبت شد — {GENDER_LABELS[choice]}</b>\n\n"
        "از این به بعد سؤال‌های شخصی (به‌ویژه بخش 🔞 ۱۸+) دقیقاً مناسب خودت از تو پرسیده می‌شود.\n"
        "💡 می‌توانی با «↻ بروزرسانی» وضعیت Lobby را ببینی.",
        v5_markup([[v5_button("↻ بروزرسانی Lobby", "V5|GAME")]]),
    )


# ----------------------------------------------------------------
# [FIX-LOBBY 3/7] نقطه‌ی ورود واحد callback ها — قبل از کل زنجیره‌ی
# قدیمی، مسیرهای حیاتی (عضویت/رضایت ۱۸+) را خودمان پاس می‌دهیم.
# توجه: این نسخه جای ar12_callback_dispatch ثبت‌شده در main را می‌گیرد
# (ثبت با نام در زمان اجرا resolve می‌شود).
# ----------------------------------------------------------------
_AR16_OLD_DISPATCH = ar12_callback_dispatch


async def ar12_callback_dispatch(update, context):
    query = getattr(update, "callback_query", None)
    if not query or not query.data:
        return
    data = str(query.data)
    uid = int(getattr(query.from_user, "id", 0) or 0)
    try:
        # ---- تعمیر نوبت/صفحه در همان لحظه (بدون بلاک) ----
        if v16_maintenance() and not is_admin(uid):
            await safe_answer_query(query, "🛠 ربات در حال بروزرسانی است؛ چند دقیقه دیگر برگرد.", True)
            return
        # ---- [FIX-LOBBY] مسیر عضویت: همیشه زنده (در حالت باز) ----
        if data.startswith("V5|L|J|") and v7_chat_is_group(update) and ar16_gate_mode() != "on":
            parts = data.split("|")
            gid = parts[3] if len(parts) > 3 else ""
            game = DATA.get("games", {}).get(gid)
            if game and game.get("status") == "lobby":
                await ar16_smart_join(query, game)
                return
        # ---- [ADULT-GATE v3] رضایت پاسخ‌دهنده‌ی ۱۸+ (فقط یک بار در عمر) ----
        if data.startswith("V7|18|ACC|") or data.startswith("V7|18|DEN|"):
            await v16_adult_consent(query, data)
            return
        # ---- [ADULT-GATE v3] تأیید یک‌باره‌ی پرسشگر برای موضوع 🔞 ----
        if data.startswith("V7|MODE|adult") and v7_chat_is_group(update):
            game = active_game(int(query.message.chat_id)) if query.message else None
            if game and game.get("status") == "active":
                if not is_admin(uid) and not get_user(uid).get("adult_ok", False):
                    await safe_answer_query(query)
                    await safe_edit_query(
                        query,
                        "🔞 <b>ورود به بخش ۱۸+</b>\n"
                        "______________________\n"
                        "این بخش سؤال‌های بسیار جنجالی و جنسی دارد.\n"
                        "✅ <b>فقط یک بار</b> این سؤال از تو پرسیده می‌شود و برای همیشه یادگرفته می‌شود.\n\n"
                        "آیا بالای ۱۸ سال هستی و می‌خواهی ادامه دهی؟",
                        v5_markup([
                            [v5_button("✅ بالای ۱۸+ هستم", "V7|18|OK|adult")],
                            [v5_button("🔙 موضوعات دیگر", "V7|TURN")],
                        ]),
                    )
                    return
        # ---- [FIX-LOBBY] دکمه‌ی شروع بازی هم در حالت باز بدون گیت مرده ----
        if data.startswith("V5|L|S|") and v7_chat_is_group(update):
            parts = data.split("|")
            gid = parts[3] if len(parts) > 3 else ""
            game = DATA.get("games", {}).get(gid)
            if game and game.get("status") == "lobby" and ar16_gate_mode() != "on":
                await v7_start_lobby(query, game)
                return
    except Exception as exc:
        audit("v16_dispatch_error", uid, None, repr(exc)[:300])
        try:
            await safe_answer_query(query, "⚠️ عملیات انجام نشد؛ دوباره امتحان کن.", True)
            return
        except Exception:
            return
    return await _AR16_OLD_DISPATCH(update, context)


# ----------------------------------------------------------------
# [ADULT-GATE v3] منطق رضایت پاسخ‌دهنده — یک بار در عمر هر حساب.
# پرسشگر هدف را انتخاب می‌کند؛ اگر هدف هنوز ۱۸+ را تأیید نکرده باشد،
# کارت رضایت در گروه برای خودِ هدف ارسال می‌شود.
# ----------------------------------------------------------------
async def v16_adult_consent(query, data):
    try:
        parts = data.split("|")
        gid = parts[3] if len(parts) > 3 else ""
        game = DATA.get("games", {}).get(gid)
        pending = (game or {}).get("v16_adult_pending") or {}
        target = int(pending.get("target") or 0)
        uid = int(query.from_user.id)
        if not game or not target or uid != target:
            await safe_answer_query(query, "🔒 این پیام مخصوص پاسخ‌دهنده‌ی انتخاب‌شده است.", True)
            return
        questioner = int(pending.get("questioner") or 0)
        game.pop("v16_adult_pending", None)
        if data.startswith("V7|18|ACC|"):
            get_user(target)["adult_ok"] = True
            audit("v16_adult_consent", target, int(game.get("chat_id", 0)), "accepted")
            save_data(force=True)
            await safe_answer_query(query, "✅ تأیید شد — این سؤال فقط همین یک بار پرسیده می‌شود.")
            await v16_ask_question(query.message, game, "adult", target, questioner)
        else:
            audit("v16_adult_declined", target, int(game.get("chat_id", 0)), "declined")
            save_data(force=True)
            await safe_answer_query(query, "نپذیرفتی — هیچ اجباری نیست.")
            try:
                await query.message.edit_text(
                    "❌ <b>پاسخ‌دهنده سؤال ۱۸+ را نپذیرفت.</b>\n"
                    f"🎤 {mention_user(questioner, name_of(questioner, game))} نفر دیگری را انتخاب کن.",
                    parse_mode=ParseMode.HTML,
                )
            except Exception:
                pass
            try:
                await query.message.reply_text(
                    v7_turn_card(game),
                    parse_mode=ParseMode.HTML,
                    reply_markup=v7_turn_markup(game, questioner),
                )
            except Exception:
                pass
    except Exception as exc:
        audit("v16_adult_consent_error", int(query.from_user.id), None, repr(exc)[:300])
        try:
            await safe_answer_query(query, "⚠️ عملیات انجام نشد.", True)
        except Exception:
            pass


# ----------------------------------------------------------------
# [FIX-LOBBY 4/7] v7_begin_prompt بازنویسی‌شده — بدون بلاک عضویت کانال؛
# با رضایت ۱۸+ برای هدف؛ و با فلیر جدید سؤال.
# ----------------------------------------------------------------
async def v7_begin_prompt(query, mode: str, target_uid: int):
    game = active_game(query.message.chat_id if query.message else 0)
    if not game or game.get("status") != "active":
        await safe_answer_query(query, "⛔ بازی فعال نیست.", True)
        return
    questioner = v7_current_questioner(game)
    if questioner is None or int(query.from_user.id) != int(questioner):
        await safe_answer_query(query, "👑 فقط پرسشگر فعلی.", True)
        return
    target_uid = int(target_uid)
    if target_uid not in {int(p) for p in game.get("players", [])} or target_uid == int(questioner):
        await safe_answer_query(query, "🎯 این بازیکن در نوبت فعلی قابل انتخاب نیست.", True)
        return
    # [ADULT-GATE v3] رضایت یک‌باره‌ی پاسخ‌دهنده
    if mode == "adult" and not get_user(target_uid).get("adult_ok", False) and not is_admin(target_uid):
        game["v16_adult_pending"] = {"target": target_uid, "questioner": int(questioner), "mode": "adult"}
        save_data(force=True)
        await safe_answer_query(query, "🔞 منتظر تأیید پاسخ‌دهنده هستیم…")
        g_icon = user_gender_icon(target_uid)
        try:
            await query.message.reply_text(
                "🔞 <b>درخواست سؤال ۱۸+</b>\n"
                "______________________\n"
                f"{g_icon} پاسخ‌دهنده: <b>{mention_user(target_uid, name_of(target_uid, game))}</b>\n"
                f"🎤 پرسشگر: {mention_user(questioner, name_of(questioner, game))}\n"
                "______________________\n"
                "پرسشگر می‌خواهد یک سؤال <b>۱۸+ و جنجالی</b> از تو بپرسد.\n"
                "✅ این تأیید <b>فقط یک بار</b> در عمر حسابت پرسیده می‌شود و پس از آن دیگر تکرار نمی‌شود.\n"
                "❌ اگر نپذیری، کسی از تو نمی‌پرسد و پرسشگر نفر دیگری را انتخاب می‌کند.",
                parse_mode=ParseMode.HTML,
                reply_markup=v5_markup([
                    [v5_button("✅ می‌پذیرم — بپرس", f"V7|18|ACC|{game['id']}")],
                    [v5_button("❌ نه، نمی‌خواهم", f"V7|18|DEN|{game['id']}")],
                ]),
            )
        except Exception:
            pass
        return
    await v16_ask_question(query.message, game, mode, target_uid, int(questioner))
    await safe_answer_query(query, "✅ سؤال ساخته شد و برای هدف ارسال شد.")


async def v16_ask_question(message, game, mode: str, target_uid: int, questioner: int):
    """ساخت و ارسال سؤال — قلب موتور V16 (جنسیت‌محور برای 🔞)."""
    target_uid = int(target_uid)
    questioner = int(questioner)
    prompt_text = v7_pick_question(game, mode, target_uid)
    mode_label = V7_MODE_LABELS.get(mode, mode)
    questioner_tag = mention_user(questioner, name_of(questioner, game))
    target_tag = mention_user(target_uid, name_of(target_uid, game))
    g_icon = user_gender_icon(target_uid)
    divider = "______________________"
    adult_flair = "\n🔞 این سؤال مخصوصِ جنسیتِ پاسخ‌دهنده انتخاب شده است." if mode == "adult" else ""
    flair = V16_MODE_FLAIR.get(mode, "")
    display = (
        f"{v7_mode_icon(mode)} <b>{escape(mode_label)}</b>\n"
        f"{divider}\n"
        f"🎤 پرسشگر: {questioner_tag}\n"
        f"🎯 پاسخ‌دهنده: {g_icon} {target_tag}\n"
        f"🔢 نوبت: <b>{int(game.get('turn_number', 1))}</b> · دور: <b>{int(game.get('round', 0)) + 1}</b>\n"
        f"{divider}\n\n"
        f"{flair}\n"
        f"<blockquote>{escape(prompt_text)}</blockquote>\n"
        f"{adult_flair}\n"
        "↩️ <b>پاسخ‌دهنده باید دقیقاً روی همین پیام Reply کند و جوابش را بنویسد.</b>"
    )
    sent = await message.reply_text(display, parse_mode=ParseMode.HTML)
    game["round"] = int(game.get("round", 0)) + 1
    game["phase"] = f"question:{mode}"
    game["reply_prompt"] = {
        "message_id": int(getattr(sent, "message_id", 0)),
        "chat_id": int(game.get("chat_id", 0)),
        "kind": mode,
        "mode": mode,
        "target_uid": target_uid,
        "questioner_uid": questioner,
        "any_player": False,
        "expires": time.time() + 180,
        "responders": [],
        "max_replies": 1,
        "created_at": now_ts(),
    }
    game.setdefault("turn_history", []).append({
        "turn": int(game.get("turn_number", 1)),
        "questioner": questioner,
        "target": target_uid,
        "mode": mode,
        "prompt": prompt_text,
        "ts": now_ts(),
    })
    game["turn_history"] = game["turn_history"][-100:]
    touch_game(game)
    save_data(force=True)


V16_MODE_FLAIR = {
    "truth": "💬 <i>صادق باش؛ دروغ اینجا ممنوع!</i>",
    "dare": "🔥 <i>جرئت داری انجامش بدی؟</i>",
    "mind": "🧠 <i>عمیق فکر کن؛ جواب سطحی ممنوع!</i>",
    "flirty": "💘 <i>ملایم و قشنگ جواب بده!</i>",
    "scenario": "🎭 <i>خودت را جای آن موقعیت بگذار!</i>",
    "secret": "🤫 <i>اعتراف واقعی، بدون نقاب!</i>",
    "drama": "😈 <i>جنجال رسمی شروع شد — صادقانه بگو!</i>",
    "memory": "📖 <i>قصه‌ات را با جزئیات تعریف کن!</i>",
    "cringe": "😳 <i>خجالت لازم نیست؛ همه قول می‌دهیم نخندیم!</i>",
    "relation": "💔 <i>از قلبت جواب بده!</i>",
    "wouldyou": "🤔 <i>فقط یکی را انتخاب کن — «هیچ‌کدام» ممنوع!</i>",
    "adult": "🔞 <i>بزرگ‌ها فقط — بدون سانسور جواب بده!</i>",
}


# ----------------------------------------------------------------
# [FIX-LOBBY 5/7] شروع بازی بدون پاکسازی کانالی بازیکنان (نسخه AR8
# قدیم بازیکن‌های بدون عضویت کانال را موقع استارت حذف می‌کرد!)
# ----------------------------------------------------------------
async def v7_start_lobby(query, game):
    uid = int(query.from_user.id)
    if not leader_of(game, uid) and not is_admin(uid):
        await safe_answer_query(query, "👑 فقط سرگروه می‌تواند بازی را شروع کند.", True)
        return
    players = [int(p) for p in game.get("players", [])]
    min_p = int(game.get("settings", {}).get("min_players", 2))
    if len(players) < min_p:
        await safe_answer_query(query, f"⏳ حداقل {min_p} بازیکن لازم است.", True)
        return
    game["status"] = "active"
    game["phase"] = "turn_waiting"
    game["started_at"] = now_ts()
    game["round"] = 0
    game["turn_number"] = 1
    game.pop("reply_prompt", None)
    game.pop("v16_adult_pending", None)
    v7_seed_turn(game)
    for p in players:
        get_user(int(p))["games"] = int(get_user(int(p)).get("games", 0)) + 1
    audit("v16_start_game", uid, int(game.get("chat_id", 0)), str(game.get("id")))
    save_data(force=True)
    await safe_answer_query(query, "🎮 بازی شروع شد!")
    current = int(game.get("current_questioner") or players[0])
    await safe_edit_query(query, v7_turn_card(game), v7_turn_markup(game, current))
    # [FIX 15b] اعلان شروع همراه با کیبورد موضوعات — همان پیام، همان لحظه.
    try:
        await query.message.reply_text(
            v7_turn_announcement(game, current).replace("نوبت بعدی شروع شد", "بازی شروع شد — نوبت اول"),
            parse_mode=ParseMode.HTML,
            reply_markup=v7_turn_markup(game, current),
        )
    except Exception:
        try:
            await query.message.reply_text(
                f"🎮 <b>ApexRival شروع شد!</b>\n\nنوبت اول: {mention_user(current, name_of(current, game))}",
                parse_mode=ParseMode.HTML,
                reply_markup=v7_turn_markup(game, current),
            )
        except Exception:
            pass


# ----------------------------------------------------------------
# [FIX-LOBBY 6/7] فهرست اهداف بدون فیلتر عضویت کانال (نسخه AR8 قدیم
# بازیکن‌های غیرعضو را از فهرست هدف حذف می‌کرد — «لیست خالی»!)
# ----------------------------------------------------------------
async def v7_show_targets(query, game, mode: str):
    questioner = v7_current_questioner(game)
    if questioner is None:
        await safe_answer_query(query, "⛔ نوبت هنوز آماده نیست.", True)
        return
    if int(query.from_user.id) != int(questioner):
        await safe_answer_query(query, "👑 فقط پرسشگر فعلی می‌تواند انتخاب کند.", True)
        return
    eligible = [int(p) for p in game.get("players", []) if int(p) != int(questioner)]
    mode_label = V7_MODE_LABELS.get(mode, mode)
    if not eligible:
        await safe_edit_query(query, v5_card("🎯 انتخاب هدف", f"حالت: <b>{escape(mode_label)}</b>", "هنوز بازیکنِ دیگری وجود ندارد."), v5_markup([[v5_button("🔙 نوبت", "V7|TURN")]]))
        return
    rows = []
    for uid in eligible:
        g_icon = user_gender_icon(uid)
        label = str(name_of(uid, game))[:22]
        rows.append([v5_button(f"🎯 {g_icon} {label}", f"V7|TARGET|{mode}|{uid}")])
    rows.append([v5_button("🔙 موضوعات", "V7|TURN")])
    rows.append(ar7_game_nav("V5|GAME"))
    adult_hint = " 🔞 سؤال بر اساس جنسیتِ پاسخ‌دهنده ساخته می‌شود." if mode == "adult" else ""
    await safe_edit_query(
        query,
        v5_card("🎯 انتخاب هدف", f"حالت انتخاب‌شده: <b>{escape(mode_label)}</b>{adult_hint}", "یک نفر را انتخاب کن؛ سؤال برای همان شخص ساخته می‌شود."),
        v5_markup(rows),
    )


# ----------------------------------------------------------------
# [FIX-LOBBY 7/7 + V16] انتخاب موضوع بدون گیت فعال‌سازی (پرسشگرِ
# تازه‌وارد هم می‌تواند فوراً بازی را جلو ببرد)
# ----------------------------------------------------------------
async def v7_mode_callback(query, context, mode: str):
    game = active_game(int(query.message.chat_id)) if query.message else None
    if not game or game.get("status") != "active":
        await safe_answer_query(query, "⛔ بازی فعالی نیست.", True)
        return
    uid = int(query.from_user.id)
    current = v7_current_questioner(game)
    if current is None or uid != int(current):
        await safe_answer_query(query, "🎤 فقط پرسشگر فعلی می‌تواند موضوع را انتخاب کند.", True)
        return
    if mode not in V7_MODE_LABELS:
        await safe_answer_query(query, "⛔ این موضوع فعال نیست.", True)
        return
    await v7_show_targets(query, game, mode)


# ----------------------------------------------------------------
# [V16-START] بازنویسی کامل /start — بدون سد کانال در حالت پیش‌فرض،
# با عضویت خودکار deep-link لابی و کارت نرم کانال (فقط یک بار).
# ----------------------------------------------------------------
async def ar15_start(update, context):
    user = getattr(update, "effective_user", None)
    msg = getattr(update, "message", None)
    if not user or not msg:
        return
    uid = int(user.id)
    bot = getattr(context, "bot", None) or APEX_RUNTIME_BOT
    if is_banned(uid) and not is_admin(uid):
        await msg.reply_text("🚫 دسترسی این حساب به ApexRival مسدود است.", reply_markup=ReplyKeyboardRemove())
        return
    if v16_maintenance() and not is_admin(uid):
        await msg.reply_text("🛠 <b>ربات در حال بروزرسانی است.</b>\nچند دقیقه دیگر دوباره /start بزن.", reply_markup=ReplyKeyboardRemove())
        return

    # ---------- شاخه‌ی گروه ----------
    if not ar12_private_only(update):
        username = await ar11_bot_username(bot)
        private_url = ar11_private_activate_url(username)
        rows = []
        if private_url:
            rows.append([ApexInlineButton("🚀 فعال‌سازی در چت خصوصی", url=private_url, style=APEX_STYLE_SUCCESS)])
        if user_gender(uid):
            await msg.reply_text(
                "✅ <b>حسابت فعال است.</b>\n\nبرای ساخت یا ورود به Lobby همین‌جا <b>/game</b> را بزن.",
                parse_mode=ParseMode.HTML,
                reply_markup=ReplyKeyboardRemove(),
            )
        else:
            await msg.reply_text(
                "🚻 <b>یک قدم مانده!</b>\n\nجنسیتت را انتخاب کن تا سؤال‌ها دقیقاً مناسب خودت ساخته شوند:",
                parse_mode=ParseMode.HTML,
                reply_markup=gender_prompt_markup(),
            )
        return

    # ---------- شاخه‌ی خصوصی ----------
    args = [str(a).strip() for a in (getattr(context, "args", None) or []) if str(a).strip()]
    source = f"start:{args[0][:40]}" if args else "private_start"
    strict_channel = False
    if ar16_gate_mode() == "on" and not is_admin(uid):
        membership, _ = await ar8_channel_membership(uid, force=True, bot=bot)
        if membership is not True:
            text = ar8_prereq_text("need_channel" if membership is False else "check_error")
            await msg.reply_text(text, parse_mode=ParseMode.HTML, reply_markup=await ar11_gate_markup(bot))
            return
        strict_channel = True

    v7_mark_started(uid, source=source)
    AR11_PRIVATE_CACHE[uid] = (time.time(), True, "direct_start")
    st = ar11_activation_state(uid)
    st["source"] = source
    st["last_verified_at"] = now_ts()
    await ar15_record_lifetime_verified(uid, bot=bot, source=source, language_code=ar15_user_language(update))
    u = get_user(uid, user.first_name or user.username or "بازیکن")

    # کارت نرم کانال — فقط یک بار در عمر حساب (حالت باز)
    if not strict_channel:
        try:
            if not u.get("v16_channel_card_ts"):
                u["v16_channel_card_ts"] = now_ts()
                save_data(force=True)
                username = await ar11_bot_username(bot)
                if username:
                    await msg.reply_text(
                        "📢 <b>اخبار و آپدیت‌های ApexRival</b>\n"
                        "اگه دوست داری از امکانات جدید و مسابقه‌ها زودتر باخبر شی، کانال ما رو دنبال کن 👇",
                        parse_mode=ParseMode.HTML,
                        reply_markup=v5_markup([[ApexInlineButton("📢 عضویت در کانال", url=REQUIRED_CHANNEL_URL, style=APEX_STYLE_PRIMARY)]]),
                    )
        except Exception:
            pass

    # [GEN] جنسیت اجباری پیش از منوی خانه
    if not user_gender(uid):
        u["gender"] = ""
        save_data(force=True)
        audit("gender_prompt_shown", uid, int(msg.chat_id), "after_activation")
        await msg.reply_text(gender_prompt_text(uid), parse_mode=ParseMode.HTML, reply_markup=gender_prompt_markup())
        return
    await msg.reply_text(
        ar12_private_home_text(uid) + "\n\n✅ <b>حساب خصوصی با موفقیت فعال شد.</b>\n🔐 <b>تأیید بعدی لازم نیست.</b>",
        parse_mode=ParseMode.HTML,
        reply_markup=ar12_private_home_markup(uid),
    )

    # ---------- [V16] عضویت deep-link لابی ----------
    if args and args[0].startswith("lobby_"):
        token = args[0][6:]
        try:
            game = ar13_find_lobby_by_invite(token)
            if not game:
                await msg.reply_text("⛔ این دعوت دیگر معتبر نیست؛ Lobby بسته شده است.")
                return
            if v5_is_player(game, uid):
                await msg.reply_text("✅ تو از قبل داخل همین Lobby هستی.\n\nحالا برگرد به گروه و وضعیت آمادگی‌ات را تنظیم کن.")
                return
            if ar13_lobby_locked(game):
                await msg.reply_text("🔒 این Lobby توسط سرگروه قفل شده و عضو جدید نمی‌پذیرد.")
                return
            max_players = int(game.get("settings", {}).get("max_players", 20))
            if len(game.get("players", [])) >= max_players:
                await msg.reply_text("⛔ ظرفیت Lobby تکمیل است.")
                return
            game.setdefault("players", []).append(uid)
            game.setdefault("names", {})[str(uid)] = user.first_name or user.username or "بازیکن"
            v5_ready_state(game)[str(uid)] = True
            touch_game(game)
            audit("v16_invite_join", uid, int(game.get("chat_id", 0)), str(game.get("id")))
            save_data(force=True)
            await msg.reply_text(
                "🎟 <b>با موفقیت وارد Lobby شدی!</b>\n\n"
                f"👥 بازیکنان: <b>{len(game['players'])}/{max_players}</b>\n"
                "💬 حالا برگرد به گروه تا ادامه بازی را ببینی.",
                parse_mode=ParseMode.HTML,
            )
            try:
                await bot.send_message(
                    int(game.get("chat_id", 0)),
                    f"🎟 {mention_user(uid, name_of(uid, game))} با لینک دعوت وارد Lobby شد! 👋",
                    parse_mode=ParseMode.HTML,
                )
            except Exception:
                pass
        except Exception as exc:
            print(f"ApexRival V16 lobby deep-link error: {exc!r}")


