# [V16-BEAUTY] کارت Lobby جدید — چیپ‌های موضوع + نوار پیشرفت + نقش‌ها
# ----------------------------------------------------------------
def ar13_lobby_text(game):
    players = [int(x) for x in game.get("players", [])]
    ready_map = v5_ready_state(game)
    min_p = int(game.get("settings", {}).get("min_players", 2))
    max_p = int(game.get("settings", {}).get("max_players", 20))
    ready_n, total_n = ar13_ready_count(game)
    enough = total_n >= min_p
    all_ready = all(bool(ready_map.get(str(uid), True)) for uid in players) if players else False
    lock_line = "🔒 ثبت‌نام <b>بسته</b>" if ar13_lobby_locked(game) else "🟢 ثبت‌نام <b>باز</b>"
    if enough and all_ready:
        status = "✅ آماده شروع"
    elif total_n < min_p:
        status = f"⏳ حداقل {min_p} نفر لازم است"
    else:
        status = "🟡 چند نفر هنوز آماده نیستند"
    lines = []
    for index, uid in enumerate(players, 1):
        mark = "🟢" if bool(ready_map.get(str(uid), True)) else "🟡"
        host_mark = " 👑" if int(uid) == int(game.get("leader_id", 0)) else ""
        lines.append(f"{mark} {index}. {user_gender_icon(uid)} {mention_user(uid, v5_name(uid, game))}{host_mark}")
    return (
        "🎮 <b>ApexRival — Lobby 2.5</b>\n"
        "______________________\n"
        f"👑 سرگروه: {mention_user(game['leader_id'], game.get('leader_name', 'سرگروه'))}\n"
        f"👥 بازیکنان: <b>{total_n}/{max_p}</b> · آماده: <b>{ready_n}/{total_n}</b>\n"
        f"{lock_line} · {status}\n"
        f"{v5_progress(total_n, max_p, 12)}\n\n"
        "<b>بازیکنان</b>\n" + ("\n".join(lines) if lines else "هنوز کسی ثبت‌نام نکرده — اولین نفر باش! 🎟") +
        "\n\n<b>موضوعات بازی:</b>\n" + V16_MODE_CHIPS +
        "\n\n💡 هر بازیکن با «🟢/🟡 آماده‌ام» وضعیتش را عوض می‌کند؛ سرگروه وقتی حداقل نفرات آماده باشند «▶️ شروع بازی» را می‌زند."
    )


# ----------------------------------------------------------------
# [V16-GAME] بسته‌ی تولید/تنظیم محتوای سفارشی (پنل ادمین ← بانک‌ها)
# ----------------------------------------------------------------
def v16_merge_custom_prompts():
    """محتوای سفارشی اضافه‌شده از پنل ادمین را به بانک‌های زنده وصل می‌کند."""
    store = DATA.setdefault("v16_custom_prompts", {})
    for key, items in list(store.items()):
        if key not in V7_BANKS_FINAL:
            V7_BANKS_FINAL[key] = []
        existing = set(V7_BANKS_FINAL.get(key, []))
        for raw in items or []:
            t = str(raw).strip()
            if t and t not in existing:
                V7_BANKS_FINAL[key].append(t)
                existing.add(t)


def v16_add_prompt(key: str, text: str) -> bool:
    key = str(key)
    text = str(text).strip()
    if key not in V7_BANKS_FINAL or not text:
        return False
    if text in V7_BANKS_FINAL[key]:
        return False
    V7_BANKS_FINAL[key].append(text)
    store = DATA.setdefault("v16_custom_prompts", {})
    store.setdefault(key, [])
    if text not in store[key]:
        store[key].append(text)
    save_data(force=True)
    return True


def v16_del_prompt(key: str, text: str) -> bool:
    key = str(key)
    text = str(text).strip()
    changed = False
    if text in V7_BANKS_FINAL.get(key, []):
        V7_BANKS_FINAL[key].remove(text)
        changed = True
    store = DATA.get("v16_custom_prompts", {}).get(key, [])
    if text in store:
        store.remove(text)
        changed = True
    if changed:
        save_data(force=True)
    return changed


v16_merge_custom_prompts()


