# [V18-PROFILE] قلاب پروفایل — کارت کوئست بعد از پروفایل ارسال می‌شود
# ----------------------------------------------------------------
_AR18_OLD_PROFILE = v5_profile_message


async def v5_profile_message(update, context):
    await _AR18_OLD_PROFILE(update, context)
    try:
        user = getattr(update, "effective_user", None)
        if user:
            await context.bot.send_message(
                int(user.id),
                v18_quest_card(int(user.id)),
                parse_mode=ParseMode.HTML,
            )
    except Exception:
        pass



# ----------------------------------------------------------------
# [V18-EDITOR] مرکز مدیریت سوالات A18 — مشاهده/افزودن/ویرایش/
# حذف/بازیابی/ورود گروهی/جست‌وجو/روشن‌وخاموش/ریست + تنظیمات گرما
# همه‌ی تغییرات در DATA ذخیره می‌شوند و پس از ری‌استارت می‌مانند.
# ----------------------------------------------------------------
A18_FLOW: dict[int, dict] = {}
A18_PAGE_SIZE = 8
A18_SEARCH_PAGE = 10


def v18_bank_label(key: str) -> str:
    base = V7_MODE_LABELS.get(key, "")
    if not base:
        base = {"penalty": "☠️ حکم‌ها", "adult_male": "🔞 ۱۸+ پسرانه", "adult_female": "🔞 ۱۸+ دخترانه"}.get(key, key)
    return base


def v18_bank_keys() -> list:
    return list(V16_BANK_KEYS_ORDER)


def v18_bank_counts(key: str) -> tuple:
    bank = V7_BANKS_FINAL.get(key, [])
    customs = len(V18_CUSTOM_TEXTS.get(key, set()) & set(bank))
    edited = 0
    rev = V18_REVERSE.get(key, {})
    for text in bank:
        if _v18_hash(text) in rev:
            edited += 1
    disabled = len(v18_disabled().get(key, []))
    return len(bank), customs, edited, disabled


def v18_prompt_marks(key: str, text: str) -> str:
    if _v18_hash(text) in V18_REVERSE.get(key, {}):
        return "🌡"
    if text in V18_CUSTOM_TEXTS.get(key, set()):
        return "✏️"
    return "🔒"


def v18_snip(text: str, limit: int = 30) -> str:
    t = str(text).strip()
    return t[:limit] + ("…" if len(t) > limit else "")


# ---------------- ثبت تغییرات ----------------

def v18_add_custom(key: str, text: str) -> bool:
    key = str(key)
    text = str(text).strip()
    if not text or key not in V7_BANKS_FINAL:
        return False
    if text in V7_BANKS_FINAL[key]:
        return False
    V7_BANKS_FINAL[key].append(text)
    store = DATA.setdefault("v18_custom_prompts", {})
    store.setdefault(key, [])
    if text not in store[key]:
        store[key].append(text)
    stats = v18_stores()["stats"]
    stats["adds"] = int(stats.get("adds", 0)) + 1
    # دستاورد نویسنده
    total_custom = len(store.get(key, []))
    if total_custom >= 10:
        v18_award(int(ADMIN_ID or 0), "v18_custom_author")
    save_data(force=True)
    return True


def v18_edit_prompt(key: str, idx: int, new_text: str) -> bool:
    key = str(key)
    new_text = str(new_text).strip()
    bank = V7_BANKS_FINAL.get(key, [])
    if not new_text or not (0 <= int(idx) < len(bank)):
        return False
    current = bank[int(idx)]
    h = _v18_hash(current)
    overrides = v18_overrides().setdefault(key, {})
    rev = V18_REVERSE.setdefault(key, {})
    # اگر این متن قبلاً ویرایش شده، همان ورودی اولیه به‌روز شود (زنجیره نشود)
    orig = rev.get(h, h)
    overrides[orig] = new_text
    rev.pop(h, None)
    bank[int(idx)] = new_text
    rev[_v18_hash(new_text)] = orig
    stats = v18_stores()["stats"]
    stats["edits"] = int(stats.get("edits", 0)) + 1
    v18_award(int(ADMIN_ID or 0), "v18_bank_editor")
    save_data(force=True)
    return True


def v18_delete_prompt(key: str, idx: int) -> bool:
    key = str(key)
    bank = V7_BANKS_FINAL.get(key, [])
    if not (0 <= int(idx) < len(bank)):
        return False
    text = bank.pop(int(idx))
    v18_disabled().setdefault(key, [])
    v18_disabled()[key].append({"h": _v18_hash(text), "text": text})
    save_data(force=True)
    return True


def v18_restore_prompt(key: str, h: str) -> bool:
    key = str(key)
    items = v18_disabled().get(key, [])
    for i, entry in enumerate(items):
        if entry.get("h") == h:
            items.pop(i)
            text = str(entry.get("text") or "").strip()
            if text and text not in V7_BANKS_FINAL.get(key, []):
                V7_BANKS_FINAL.setdefault(key, []).append(text)
            save_data(force=True)
            return True
    return False


def v18_reset_bank(key: str) -> bool:
    key = str(key)
    if key not in V18_FACTORY:
        return False
    V7_BANKS_FINAL[key] = list(V18_FACTORY[key])
    v18_overrides().pop(key, None)
    v18_disabled().pop(key, None)
    DATA.get("v16_custom_prompts", {}).pop(key, None)
    DATA.get("v18_custom_prompts", {}).pop(key, None)
    V18_REVERSE.pop(key, None)
    V18_CUSTOM_TEXTS[key] = set()
    save_data(force=True)
    v18_apply_overrides_and_disables()
    return True


def v18_toggle_topic(key: str) -> bool:
    key = str(key)
    off = v18_topics_off()
    if key in off:
        off.remove(key)
        result = True
    else:
        if key in ("truth", "dare"):
            return False  # دو موضوع پایه غیرقابل خاموش‌کردن‌اند
        off.append(key)
        result = False
    save_data(force=True)
    return result


# ---------------- رابط کاربری ----------------

def v18_editor_home_body() -> str:
    stats = v18_stores()["stats"]
    total = sum(len(v) for v in V7_BANKS_FINAL.values())
    disabled_total = sum(len(v) for v in v18_disabled().values())
    overrides_total = sum(len(v) for v in v18_overrides().values())
    custom_total = sum(len(v) for v in DATA.get("v18_custom_prompts", {}).values()) + sum(len(v) for v in DATA.get("v16_custom_prompts", {}).values())
    heat = v18_heat_conf()
    return (
        "🛠 <b>مدیریت سوالات</b>\n"
        "━━━━━━━━━━━━━━━━━━\n"
        f"📚 مجموع سوال‌ها: <b>{fmt_num(total)}</b> در <b>{len(v18_bank_keys())}</b> بانک\n"
        f"✏️ سفارشی: <b>{custom_total}</b> · 🌡 ویرایش‌شده: <b>{overrides_total}</b> · 🗑 حذف‌شده: <b>{disabled_total}</b>\n"
        f"🌡 گرما: 🟢→🟠 بعد سوال <b>{int(heat.get('t2', 4))}</b> · 🟠→🔴 بعد سوال <b>{int(heat.get('t3', 8))}</b>\n"
        f"🚫 موضوعات خاموش: <b>{len(v18_topics_off())}</b>\n"
        f"📊 پرسش‌های ساخته‌شده از V18: <b>{fmt_num(sum(int(x) for x in stats.get('banks', {}).values()))}</b>\n"
        "━━━━━━━━━━━━━━━━━━\n"
        "بانک موردنظر را انتخاب کن 👇"
    )


def v18_editor_home_markup():
    rows = []
    pair = []
    for key in v18_bank_keys():
        count = len(V7_BANKS_FINAL.get(key, []))
        off = " 🚫" if v18_topic_disabled(key) else ""
        pair.append(v5_button(f"{v18_bank_label(key)}{off} ({count})", f"A18|BANK|{key}|0"))
        if len(pair) == 2:
            rows.append(pair)
            pair = []
    if pair:
        rows.append(pair)
    rows.append([
        v5_button("🌡 تنظیمات گرما", "A18|HEAT"),
        v5_button("📊 آمار", "A18|STATS"),
    ])
    rows.append([v5_button("📖 راهنمای موضوعات", "A18|GUIDE")])
    rows.append([v5_button("⌂ خانه مدیریت", "A16|HOME")])
    return v5_markup(rows)


def v18_bank_page(key: str, page: int = 0):
    bank = V7_BANKS_FINAL.get(key, [])
    size = A18_PAGE_SIZE
    page = max(0, min(page, max(0, (len(bank) - 1) // size)))
    chunk = bank[page * size:(page + 1) * size]
    rows = []
    base = page * size
    for i, text in enumerate(chunk):
        mark = v18_prompt_marks(key, text)
        rows.append([v5_button(f"{mark} {v18_snip(text)}", f"A18|VIEW|{key}|{base + i}")])
    nav = []
    if page > 0:
        nav.append(v5_button("◀️ قبلی", f"A18|BANK|{key}|{page - 1}"))
    nav.append(v5_button(f"📄 {fmt_num(len(bank))}", "A18|NONE"))
    if (page + 1) * size < len(bank):
        nav.append(v5_button("بعدی ▶️", f"A18|BANK|{key}|{page + 1}"))
    rows.append(nav)
    disabled_n = len(v18_disabled().get(key, []))
    extra = [
        v5_button("➕ افزودن", f"A18|ADD|{key}"),
        v5_button("📥 ورود گروهی", f"A18|BULK|{key}"),
    ]
    rows.append(extra)
    rows.append([
        v5_button("🔍 جست‌وجو", f"A18|SEARCH|{key}"),
        v5_button("📤 خروجی", f"A18|EXPORT|{key}"),
    ])
    tool_row = [v5_button("🚫 روشن/خاموش موضوع" if not v18_topic_disabled(key) else "🟢 فعال‌سازی موضوع", f"A18|TOGGLE|{key}")]
    if disabled_n:
        tool_row.append(v5_button(f"♻️ حذف‌شده‌ها ({disabled_n})", f"A18|DIS|{key}|0"))
    rows.append(tool_row)
    rows.append([v5_button("⚠️ ریست بانک", f"A18|RESET|{key}"), v5_button("🔙 بانک‌ها", "A18|HOME")])
    total, customs, edited, disabled = v18_bank_counts(key)
    body = (
        f"🛠 <b>{escape(v18_bank_label(key))}</b>\n"
        "━━━━━━━━━━━━━━━━━━\n"
        f"📚 تعداد: <b>{fmt_num(total)}</b> · ✏️ سفارشی: <b>{customs}</b> · 🌡 ویرایش: <b>{edited}</b> · 🗑 حذف: <b>{disabled}</b>\n"
        f"نمایش: <b>{page * size + 1}–{min((page + 1) * size, len(bank))}</b>\n"
        "━━━━━━━━━━━━━━━━━━\n"
        "🔒 اصلی · ✏️ سفارشی · 🌰 ویرایش‌شده\n"
        "برای ویرایش یا حذف، سوال را انتخاب کن 👇"
    )
    return body, v5_markup(rows)


def v18_prompt_view_body(key: str, idx: int):
    bank = V7_BANKS_FINAL.get(key, [])
    if not (0 <= idx < len(bank)):
        return None, None
    text = bank[idx]
    mark = v18_prompt_marks(key, text)
    status = {"🔒": "اصلی (کارخانه)", "✏️": "سفارشی (افزوده‌شده)", "🌡": "ویرایش‌شده"}[mark]
    heat = "🟢/🟠/🔴 آرام تا آتیشی"
    # موقعیت تقریبی گرما
    n = len(bank)
    if n > 3:
        third = max(1, n // 3)
        pos = "🟢 آرام" if idx < third else ("🟠 داغ" if idx < 2 * third else "🔴 آتیشی")
        heat = pos
    body = (
        f"❓ <b>سوال #{fmt_num(idx + 1)}</b> — {escape(v18_bank_label(key))}\n"
        "━━━━━━━━━━━━━━━━━━\n"
        f"وضعیت: <b>{status}</b> · پله‌ی گرما: <b>{heat}</b>\n"
        "━━━━━━━━━━━━━━━━━━\n"
        f"<blockquote>{escape(text)}</blockquote>\n"
        "━━━━━━━━━━━━━━━━━━\n"
        "✏️ ویرایش = ارسال متن جدید · 🗑 حذف = پنهان‌سازی (قابل بازیابی)"
    )
    rows = [
        [v5_button("✏️ ویرایش سوال", f"A18|EDIT|{key}|{idx}"),
         v5_button("🗑 حذف", f"A18|DEL|{key}|{idx}")],
    ]
    nav = []
    if idx > 0:
        nav.append(v5_button("◀️ قبلی", f"A18|VIEW|{key}|{idx - 1}"))
    nav.append(v5_button(f"📄 {idx + 1}/{fmt_num(len(bank))}", "A18|NONE"))
    if idx + 1 < len(bank):
        nav.append(v5_button("بعدی ▶️", f"A18|VIEW|{key}|{idx + 1}"))
    rows.append(nav)
    rows.append([v5_button("🔙 بانک", f"A18|BANK|{key}|{idx // A18_PAGE_SIZE}"), v5_button("⌂ بانک‌ها", "A18|HOME")])
    return body, v5_markup(rows)


def v18_disabled_page(key: str, page: int = 0):
    items = v18_disabled().get(key, [])
    if not items:
        return ("♻️ <b>حذف‌شده‌ها</b>\n━━━━━━━━━━━━━━━━━━\nچیزی حذف نشده است.",
                v5_markup([[v5_button("🔙 بانک", f"A18|BANK|{key}|0")]]))
    size = A18_PAGE_SIZE
    page = max(0, min(page, max(0, (len(items) - 1) // size)))
    chunk = items[page * size:(page + 1) * size]
    rows = []
    for entry in chunk:
        rows.append([v5_button(f"↩️ {v18_snip(str(entry.get('text', '')))}", f"A18|BACK|{key}|{entry.get('h')}")])
    nav = []
    if page > 0:
        nav.append(v5_button("◀️ قبلی", f"A18|DIS|{key}|{page - 1}"))
    if (page + 1) * size < len(items):
        nav.append(v5_button("بعدی ▶️", f"A18|DIS|{key}|{page + 1}"))
    if nav:
        rows.append(nav)
    rows.append([v5_button("🔙 بانک", f"A18|BANK|{key}|0")])
    body = (
        "♻️ <b>سوال‌های حذف‌شده</b>\n"
        "━━━━━━━━━━━━━━━━━━\n"
        f"تعداد: <b>{len(items)}</b>\n"
        "برای بازیابی، سوال را انتخاب کن 👇"
    )
    return body, v5_markup(rows)


def v18_heat_page_body() -> str:
    conf = v18_heat_conf()
    stats = v18_stores()["stats"]
    heat_uses = stats.get("heat", {})
    return (
        "🌡 <b>تنظیمات گرمای بازی</b>\n"
        "━━━━━━━━━━━━━━━━━━\n"
        "گرمای تصاعدی یعنی سوال‌ها آرام شروع می‌شوند و با جلو رفتن بازی، "
        "جسورانه‌تر و داغ‌تر می‌شوند.\n"
        "━━━━━━━━━━━━━━━━━━\n"
        f"🟢 آرام: سوال ۱ تا <b>{int(conf.get('t2', 4)) - 1}</b>\n"
        f"🟠 داغ: سوال <b>{int(conf.get('t2', 4))}</b> تا <b>{int(conf.get('t3', 8)) - 1}</b>\n"
        f"🔴 آتیشی: سوال <b>{int(conf.get('t3', 8))}</b> به بعد\n"
        "━━━━━━━━━━━━━━━━━━\n"
        f"توزیع پرسش‌ها تا امروز: 🟢 <b>{int(heat_uses.get('1', 0))}</b> · "
        f"🟠 <b>{int(heat_uses.get('2', 0))}</b> · 🔴 <b>{int(heat_uses.get('3', 0))}</b>\n"
        "آستانه‌ها را با دکمه‌های زیر تنظیم کن 👇"
    )


def v18_heat_markup():
    conf = v18_heat_conf()
    t2 = int(conf.get("t2", 4))
    t3 = int(conf.get("t3", 8))
    return v5_markup([
        [
            v5_button(f"🟠 شروع داغ: {max(2, t2 - 1)} ◀️", f"A18|HSET|t2|-1"),
            v5_button(f"🟠 شروع داغ: {t2}", "A18|NONE"),
            v5_button(f"▶️ {t2 + 1}", f"A18|HSET|t2|1"),
        ],
        [
            v5_button(f"🔴 شروع آتیشی: {max(3, t3 - 1)} ◀️", f"A18|HSET|t3|-1"),
            v5_button(f"🔴 شروع آتیشی: {t3}", "A18|NONE"),
            v5_button(f"▶️ {t3 + 1}", f"A18|HSET|t3|1"),
        ],
        [v5_button("🔙 مدیریت سوالات", "A18|HOME")],
    ])


def v18_stats_body() -> str:
    stats = v18_stores()["stats"]
    banks = stats.get("banks", {})
    top = sorted(banks.items(), key=lambda kv: int(kv[1]), reverse=True)[:8]
    top_lines = [f"  {v18_bank_label(k)}: <b>{fmt_num(int(v))}</b>" for k, v in top if int(v) > 0]
    users_v18 = sum(1 for u in DATA.get("users", {}).values() if int(u.get("v18_answer_count", 0)) > 0)
    total_answers = sum(int(u.get("v18_answer_count", 0)) for u in DATA.get("users", {}).values())
    quests_done = int(stats.get("quests_done", 0))
    return (
        "📊 <b>آمار زنده‌ی V18</b>\n"
        "━━━━━━━━━━━━━━━━━━\n"
        f"👥 بازیکنان فعال V18: <b>{fmt_num(users_v18)}</b>\n"
        f"💬 پاسخ‌های ثبت‌شده: <b>{fmt_num(total_answers)}</b>\n"
        f"📋 کوئست‌های کامل‌شده: <b>{fmt_num(quests_done)}</b>\n"
        f"✏️ سوال‌های ویرایش‌شده: <b>{int(stats.get('edits', 0))}</b> · ➕ افزوده‌شده: <b>{int(stats.get('adds', 0))}</b>\n"
        "━━━━━━━━━━━━━━━━━━\n"
        "<b>محبوب‌ترین بانک‌ها:</b>\n" + ("\n".join(top_lines) if top_lines else "  هنوز سوالی ساخته نشده.")
    )


def v18_guide_body() -> str:
    lines = []
    for key, (title, desc) in V18_TOPIC_GUIDES.items():
        off = " <i>(خاموش)</i>" if v18_topic_disabled(key) else ""
        lines.append(f"{title}{off}\n{escape(desc)}")
    extra = "\n\n".join(f"<b>❓ {escape(t)}</b>\n{escape(d)}" for t, d in V18_HELP_CENTER_EXTRA)
    return (
        "📖 <b>مرکز راهنمای بازی</b>\n"
        "━━━━━━━━━━━━━━━━━━\n"
        + "\n\n".join(lines)
        + "\n\n━━━━━━━━━━━━━━━━━━\n" + extra
    )



# ----------------------------------------------------------------
# [V18-ROUTER] مسیریاب A18| — همه‌ی دکمه‌های مدیر سوالات
# ----------------------------------------------------------------
async def v18_admin_router(update, context):
    query = getattr(update, "callback_query", None)
    if not query or not query.data:
        return
    data = str(query.data)
    if not data.startswith("A18|"):
        return
    uid = int(query.from_user.id)
    if not is_admin(uid):
        await safe_answer_query(query, "🚫 فقط Super Admin.", True)
        return
    await safe_answer_query(query)
    parts = data.split("|")
    section = parts[1] if len(parts) > 1 else "HOME"
    arg = parts[2] if len(parts) > 2 else ""
    extra = parts[3] if len(parts) > 3 else ""
    try:
        if section == "HOME":
            await safe_edit_query(query, v18_editor_home_body(), v18_editor_home_markup())
            return
        if section == "NONE":
            return

        # ---------------- بانک‌ها ----------------
        if section == "BANK":
            key = str(arg)
            if key not in V7_BANKS_FINAL:
                await safe_answer_query(query, "⛔ بانک پیدا نشد.", True)
                return
            page = int(extra or 0)
            body, markup = v18_bank_page(key, page)
            await safe_edit_query(query, body, markup)
            return
        if section == "VIEW":
            key = str(arg)
            idx = int(extra or 0)
            body, markup = v18_prompt_view_body(key, idx)
            if body is None:
                await safe_answer_query(query, "⛔ سوال پیدا نشد (شاید حذف شده).", True)
                body, markup = v18_bank_page(key, 0)
                await safe_edit_query(query, body, markup)
                return
            await safe_edit_query(query, body, markup)
            return
        if section == "EDIT":
            key = str(arg)
            idx = int(extra or 0)
            bank = V7_BANKS_FINAL.get(key, [])
            if not (0 <= idx < len(bank)):
                await safe_answer_query(query, "⛔ سوال پیدا نشد.", True)
                return
            A18_FLOW[uid] = {"t": "edit", "key": key, "idx": idx}
            body, markup = v18_prompt_view_body(key, idx)
            await safe_edit_query(
                query,
                (body or "") + "\n\n✏️ <b>حالت ویرایش فعال شد</b>\nمتن جدید این سوال را بفرست:",
                v5_markup([[v5_button("❌ لغو", f"A18|VIEW|{key}|{idx}")]]),
            )
            return
        if section == "DEL":
            key = str(arg)
            idx = int(extra or 0)
            ok = v18_delete_prompt(key, idx)
            await safe_answer_query(query, "🗑 حذف شد — از بخش «حذف‌شده‌ها» قابل بازیابیه." if ok else "⚠️ حذف نشد.", not ok)
            audit("v18_prompt_delete", uid, None, f"{key}:{idx}")
            body, markup = v18_bank_page(key, max(0, (idx - 1) // A18_PAGE_SIZE))
            await safe_edit_query(query, body, markup)
            return
        if section == "DIS":
            key = str(arg)
            page = int(extra or 0)
            body, markup = v18_disabled_page(key, page)
            await safe_edit_query(query, body, markup)
            return
        if section == "BACK":
            key = str(arg)
            h = str(extra)
            ok = v18_restore_prompt(key, h)
            await safe_answer_query(query, "✅ بازیابی شد و به بانک برگشت." if ok else "⚠️ بازیابی نشد.", not ok)
            audit("v18_prompt_restore", uid, None, key)
            body, markup = v18_bank_page(key, 0)
            await safe_edit_query(query, body, markup)
            return

        # ---------------- افزودن / ورود گروهی ----------------
        if section == "ADD":
            key = str(arg)
            if key not in V7_BANKS_FINAL:
                await safe_answer_query(query, "⛔ بانک پیدا نشد.", True)
                return
            A18_FLOW[uid] = {"t": "add", "key": key}
            await safe_edit_query(
                query,
                f"➕ <b>افزودن سوال به «{escape(v18_bank_label(key))}»</b>\n\n"
                "متن سوال/جرئت را بفرست:\n"
                "💡 سوال‌های گرم می‌توانند با 🌡/🔥/🔞 شروع بشن.",
                v5_markup([[v5_button("❌ لغو", f"A18|BANK|{key}|0")]]),
            )
            return
        if section == "BULK":
            key = str(arg)
            if key not in V7_BANKS_FINAL:
                await safe_answer_query(query, "⛔ بانک پیدا نشد.", True)
                return
            A18_FLOW[uid] = {"t": "bulk", "key": key}
            await safe_edit_query(
                query,
                f"📥 <b>ورود گروهی به «{escape(v18_bank_label(key))}»</b>\n\n"
                "چند سوال را هرکدام در یک خط بفرست (هر خط = یک سوال).\n"
                "حداکثر ۵۰ خط در هر پیام.",
                v5_markup([[v5_button("❌ لغو", f"A18|BANK|{key}|0")]]),
            )
            return
        if section == "SEARCH":
            key = str(arg)
            A18_FLOW[uid] = {"t": "search", "key": key}
            await safe_edit_query(
                query,
                f"🔍 <b>جست‌وجو در «{escape(v18_bank_label(key))}»</b>\n\nبخشی از متن سوال را بفرست:",
                v5_markup([[v5_button("❌ لغو", f"A18|BANK|{key}|0")]]),
            )
            return
        if section == "EXPORT":
            key = str(arg)
            bank = V7_BANKS_FINAL.get(key, [])
            if not bank:
                await safe_answer_query(query, "⛔ بانک خالی است.", True)
                return
            await safe_answer_query(query, f"📤 در حال ارسال {fmt_num(len(bank))} سوال…")
            lines = [f"{i + 1}. {text}" for i, text in enumerate(bank)]
            chunk_size = 35
            chunks = [lines[i:i + chunk_size] for i in range(0, len(lines), chunk_size)]
            sent = 0
            for ch in chunks:
                try:
                    await context.bot.send_message(
                        int(query.message.chat_id),
                        f"📤 <b>{escape(v18_bank_label(key))}</b> — بخش {sent + 1}/{len(chunks)}\n━━━━━━━━━━━━━━━━━━\n" + "\n".join(escape(x) for x in ch),
                        parse_mode=ParseMode.HTML,
                    )
                    sent += 1
                    await asyncio.sleep(0.4)
                except Exception:
                    break
            audit("v18_bank_export", uid, None, f"{key}:{len(bank)}")
            return

        # ---------------- ابزارها ----------------
        if section == "TOGGLE":
            key = str(arg)
            turned_on = v18_toggle_topic(key)
            if key in ("truth", "dare") and not turned_on:
                await safe_answer_query(query, "⚠️ اعتراف و جرئت پایه‌ی بازی‌اند و خاموش نمی‌شوند.", True)
                return
            await safe_answer_query(query, "🟢 موضوع فعال شد." if turned_on else "🚫 موضوع خاموش شد و از گرید نوبت حذف می‌شود.")
            audit("v18_topic_toggle", uid, None, f"{key}:{turned_on}")
            body, markup = v18_bank_page(key, 0)
            await safe_edit_query(query, body, markup)
            return
        if section == "RESET":
            key = str(arg)
            await safe_edit_query(
                query,
                f"⚠️ <b>ریست بانک «{escape(v18_bank_label(key))}»</b>\n"
                "━━━━━━━━━━━━━━━━━━\n"
                "همه‌ی سوال‌های سفارشی، ویرایش‌ها و حذف‌های این بانک پاک می‌شوند و بانک به حالت کارخانه برمی‌گردد.\n"
                "این عمل قابل بازگشت نیست!",
                v5_markup([
                    [v5_button("✅ بله، ریست کن", f"A18|RESETOK|{key}")],
                    [v5_button("❌ انصراف", f"A18|BANK|{key}|0")],
                ]),
            )
            return
        if section == "RESETOK":
            key = str(arg)
            ok = v18_reset_bank(key)
            await safe_answer_query(query, "♻️ بانک ریست شد." if ok else "⚠️ ریست نشد.", not ok)
            audit("v18_bank_reset", uid, None, key)
            body, markup = v18_bank_page(key, 0)
            await safe_edit_query(query, body, markup)
            return

        # ---------------- گرما و آمار ----------------
        if section == "HEAT":
            await safe_edit_query(query, v18_heat_page_body(), v18_heat_markup())
            return
        if section == "HSET":
            which = str(arg)  # t2 یا t3
            delta = int(extra or 0)
            conf = v18_heat_conf()
            t2 = int(conf.get("t2", 4))
            t3 = int(conf.get("t3", 8))
            if which == "t2":
                t2 = max(2, min(20, t2 + delta))
                t3 = max(t2 + 1, t3)
            else:
                t3 = max(3, min(30, t3 + delta))
                t2 = min(t2, t3 - 1)
            conf["t2"] = t2
            conf["t3"] = t3
            save_data(force=True)
            audit("v18_heat_set", uid, None, f"{t2}/{t3}")
            await safe_answer_query(query, f"🌡 ذخیره شد: داغ از سوال {t2} · آتیشی از سوال {t3}.")
            await safe_edit_query(query, v18_heat_page_body(), v18_heat_markup())
            return
        if section == "STATS":
            await safe_edit_query(query, v18_stats_body(), v5_markup([
                [v5_button("🔄 بروزرسانی", "A18|STATS")],
                [v5_button("🔙 مدیریت سوالات", "A18|HOME")],
            ]))
            return
        if section == "GUIDE":
            await safe_edit_query(query, v18_guide_body(), v5_markup([
                [v5_button("🔙 مدیریت سوالات", "A18|HOME")],
            ]))
            return
    except Exception as exc:
        audit("v18_admin_router_error", uid, None, repr(exc)[:300])
        try:
            await safe_answer_query(query, "⚠️ خطا در پردازش — دوباره امتحان کن.", True)
        except Exception:
            pass


# ----------------------------------------------------------------
# [V18-FLOW] فلوهای متنی مدیر سوالات — قبل از زنجیره‌ی A16
# ----------------------------------------------------------------
async def v18_admin_flow_text(update, context) -> bool:
    msg = getattr(update, "message", None)
    if not msg or not msg.text:
        return False
    uid = int(getattr(getattr(update, "effective_user", None), "id", 0) or 0)
    if not uid or not is_admin(uid):
        return False
    flow = A18_FLOW.get(uid)
    if not flow:
        return False
    text = str(msg.text).strip()
    if text.startswith("/"):
        A18_FLOW.pop(uid, None)
        return False
    t = str(flow.get("t"))
    try:
        if text in ("لغو", "❌ لغو", "cancel"):
            A18_FLOW.pop(uid, None)
            await msg.reply_text("✅ عملیات لغو شد.")
            return True
        if t == "edit":
            A18_FLOW.pop(uid, None)
            key = str(flow.get("key"))
            idx = int(flow.get("idx") or 0)
            if len(text) < 3:
                await msg.reply_text("⚠️ متن خیلی کوتاه است؛ دوباره بفرست.")
                return True
            if v18_edit_prompt(key, idx, text[:600]):
                audit("v18_prompt_edit", uid, None, f"{key}:{idx}")
                await msg.reply_text(
                    "🌡 <b>سوال ویرایش شد!</b>\n"
                    f"بانک: {escape(v18_bank_label(key))} · سوال #{fmt_num(idx + 1)}",
                    parse_mode=ParseMode.HTML,
                    reply_markup=v5_markup([[v5_button("👁 مشاهده نتیجه", f"A18|VIEW|{key}|{idx}")]]),
                )
            else:
                await msg.reply_text("⚠️ ویرایش نشد (متن نامعتبر).")
            return True
        if t == "add":
            A18_FLOW.pop(uid, None)
            key = str(flow.get("key"))
            if v18_add_custom(key, text[:600]):
                audit("v18_prompt_add", uid, None, key)
                await msg.reply_text(
                    f"✅ به بانک «{escape(v18_bank_label(key))}» اضافه شد (مجموع: {fmt_num(len(V7_BANKS_FINAL.get(key, [])))}).",
                    parse_mode=ParseMode.HTML,
                    reply_markup=v5_markup([[v5_button("📝 مشاهده بانک", f"A18|BANK|{key}|0")]]),
                )
            else:
                await msg.reply_text("⚠️ اضافه نشد (خالی یا تکراری).")
            return True
        if t == "bulk":
            A18_FLOW.pop(uid, None)
            key = str(flow.get("key"))
            lines = [ln.strip() for ln in text.splitlines() if ln.strip()][:50]
            added = 0
            for ln in lines:
                if v18_add_custom(key, ln[:600]):
                    added += 1
            audit("v18_prompt_bulk", uid, None, f"{key}:{added}/{len(lines)}")
            await msg.reply_text(
                f"📥 <b>ورود گروهی انجام شد</b>\n"
                f"اضافه‌شده: <b>{added}</b> از <b>{len(lines)}</b> خط\n"
                f"مجموع بانک: <b>{fmt_num(len(V7_BANKS_FINAL.get(key, [])))}</b>",
                parse_mode=ParseMode.HTML,
                reply_markup=v5_markup([[v5_button("📝 مشاهده بانک", f"A18|BANK|{key}|0")]]),
            )
            return True
        if t == "search":
            A18_FLOW.pop(uid, None)
            key = str(flow.get("key"))
            q = text.lower()
            bank = V7_BANKS_FINAL.get(key, [])
            matches = [i for i, x in enumerate(bank) if q in str(x).lower()][:A18_SEARCH_PAGE]
            if not matches:
                await msg.reply_text("❌ چیزی پیدا نشد.")
                return True
            rows = [[v5_button(f"{v18_prompt_marks(key, bank[i])} {v18_snip(bank[i])}", f"A18|VIEW|{key}|{i}")] for i in matches]
            rows.append([v5_button("🔙 بانک", f"A18|BANK|{key}|0")])
            await msg.reply_text(
                f"🔍 <b>نتایج ({len(matches)})</b> — برای مشاهده انتخاب کن:",
                parse_mode=ParseMode.HTML,
                reply_markup=v5_markup(rows),
            )
            return True
    except Exception as exc:
        A18_FLOW.pop(uid, None)
        print(f"ApexRival V18 flow warning: {exc!r}")
        try:
            await msg.reply_text(f"❌ {escape(str(exc))}")
        except Exception:
            pass
        return True
    return False



# ----------------------------------------------------------------
# [V18-TURN] گرید نوبت با موضوعات فعال (خاموش‌ها حذف می‌شوند)
# + نمایش گرمای بازی در کارت نوبت
# ----------------------------------------------------------------
_AR18_OLD_TURN_MARKUP = v7_turn_markup


def v7_turn_markup(game, viewer_uid):
    q = v7_current_questioner(game)
    if q is None:
        return v5_markup([v5_nav("V5|GAME")])
    if int(viewer_uid) == int(q):
        rows = []
        pair = []
        for key, label in v18_topic_buttons():
            pair.append(v5_button(label, f"V7|MODE|{key}"))
            if len(pair) == 2:
                rows.append(pair)
                pair = []
        if pair:
            rows.append(pair)
        rows.append([v5_button("🎲 تغییر نوبت", "V7|SKIP"), v5_button("ℹ️ راهنما", "V7|HELP")])
        rows.append(ar7_game_nav("V5|GAME"))
    else:
        rows = [
            [v5_button("📊 وضعیت نوبت", "V7|TURN")],
            [v5_button("☠️ حکم من", "V7|PENALTY"), v5_button("🏆 امتیازها", "V7|SCORES")],
            [v5_button("ℹ️ راهنما", "V7|HELP")],
            ar7_game_nav("V5|GAME"),
        ]
    return v5_markup(rows)


_AR18_OLD_TURN_CARD = v7_turn_card


def v7_turn_card(game):
    base = _AR18_OLD_TURN_CARD(game)
    try:
        heat = v18_game_heat(game)
        base = (
            f"{base}\n"
            f"🌡 گرمای بازی: <b>{v18_heat_chip(heat)}</b> — سوال‌ها با پیشرفت بازی داغ‌تر می‌شوند"
        )
    except Exception:
        pass
    return base


