# ----------------------------------------------------------------
# [V18-CHECK] سلف-چک لایه — هنگام لود اجرا می‌شود
# ----------------------------------------------------------------
def v18_self_check() -> None:
    # ۱) همه‌ی ۱۵ بانک اصلی پر و یکتا
    required = ["truth", "dare", "secret", "drama", "flirty", "scenario", "mind", "wouldyou",
                "memory", "relation", "cringe", "adult", "adult_male", "adult_female", "penalty",
                "dream", "regret", "future"]
    for key in required:
        bank = V7_BANKS_FINAL.get(key, [])
        assert len(bank) >= 20, f"bank too small: {key} ({len(bank)})"
        assert len(bank) == len(set(bank)), f"duplicates in {key}"
    # ۲) لیبل برای هر ۱۵ موضوع
    for key, _label in V16_MODE_ORDER:
        assert key in V7_MODE_LABELS, f"missing label: {key}"
    # ۳) گرید نوبت باید ۱۵ دکمه موضوع داشته باشد
    fake_game = {"players": [1, 2, 3], "turn_order": [1, 2, 3], "turn_index": 0,
                 "current_questioner": 1, "turn_number": 1, "round": 0, "round_scores": {}}
    markup = v7_turn_markup(fake_game, 1)
    mode_buttons = []
    for row in getattr(markup, "inline_keyboard", []):
        for b in row:
            data = getattr(b, "callback_data", None)
            if data is not None:
                assert len(str(data).encode("utf-8")) <= 64, data
                if str(data).startswith("V7|MODE|"):
                    mode_buttons.append(str(data).split("|")[2])
    assert len(mode_buttons) == 15, f"expected 15 mode buttons, got {len(mode_buttons)}"
    for key in ("truth", "dare", "secret", "drama", "flirty", "scenario", "mind", "wouldyou",
                "memory", "relation", "cringe", "adult", "dream", "regret", "future"):
        assert key in mode_buttons, f"mode button missing: {key}"
    # ۴) موتور گرما
    assert v18_game_heat({"round": 0}) == 1
    assert v18_game_heat({"round": 99}) == 3
    window = v18_heat_window(list(range(30)), 1)
    assert len(window) == 10 and 0 in window and 9 in window and 10 not in window
    # ۵) پیکر انتخاب سوال — یک نمونه واقعی
    probe_game = {"players": [1, 2], "turn_number": 1, "round": 0, "round_scores": {}}
    p1 = v7_pick_question(probe_game, "truth", None)
    p2 = v7_pick_question(probe_game, "truth", None)
    assert isinstance(p1, str) and p1 and p1 != p2
    # ۶) پنل ادمین سالم
    assert v18_editor_home_markup() is not None
    body, mk = v18_bank_page("truth", 0)
    assert mk is not None and body
    # ۷) رشته‌های راهنما
    assert len(V18_TOPIC_GUIDES) == 15
    assert len(V18_TOPIC_INTROS) == 15
    # ۸) کوئست‌ها
    ids = v18_daily_quest_ids(123456789)
    assert len(ids) == 3 and len({q["id"] for q in ids}) == 3
    print(
        f"ApexRival V18 self-check OK | banks={len(V7_BANKS_FINAL)} | "
        f"prompts={sum(len(v) for v in V7_BANKS_FINAL.values())} | modes=15 | "
        f"heat=on | question-editor=on | quests=on | factory-reset=on"
    )


v18_self_check()


# ----------------------------------------------------------------
# [V18-MAIN] لانچر نهایی — همه‌ی چک‌های اصلی + چک V18 + استارت
# ----------------------------------------------------------------
def main_apexrival_18():
    if not BOT_TOKEN:
        raise RuntimeError("BOT_TOKEN is missing")
    _ar8_final_markup_self_check()
    _ar11_static_self_check()
    ar12_static_self_check()
    ar13_static_self_check()
    ar14_static_self_check()
    ar15_static_self_check()
    v18_self_check()
    start_health_server()
    application = Application.builder().token(BOT_TOKEN).post_init(ar15_post_init).build()
    ar15_register_handlers(application)
    application.add_error_handler(ar9_error_handler)
    print(
        f"{BOT_NAME} starting | mega-expansion=V18 | unique-commands=on | "
        "combined-onboarding=on | ads=on | anti-collision=on | fresh-lobby=on | "
        "scope-repair=on | heat-engine=on | question-editor=on | daily-quests=on"
    )
    application.run_polling(drop_pending_updates=True)


